	return c.packetWrites.writeOne(&c.access, c.ExtendedConn, buffer, destination, &c.destination, func(b *buf.Buffer, d M.Socksaddr) (*buf.Buffer, error) {
		return prepareServerPacket(b, d, false, &c.responseWritten)
	})
}

