package smux

import (
	"sync"
)

// _itimediff returns the time difference between two uint32 values.
// The result is a signed 32-bit integer representing the difference between 'later' and 'earlier'.
func _itimediff(later, earlier uint32) int32 {
	return (int32)(later - earlier)
}

// shaperHeap is a min-heap of writeRequest.
// It orders writeRequests by class first, then by sequence number within the same class.
type shaperHeap []writeRequest

func (h shaperHeap) Len() int { return len(h) }

// Less determines the ordering of elements in the heap.
// Requests are ordered by their class first. If two requests have the same class,
// they are ordered by their sequence numbers.
func (h shaperHeap) Less(i, j int) bool {
	if h[i].class != h[j].class {
		return h[i].class < h[j].class
	}
	return _itimediff(h[j].seq, h[i].seq) > 0
}

func (h shaperHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *shaperHeap) Push(x any)   { *h = append(*h, x.(writeRequest)) }

func (h *shaperHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	old[n-1] = writeRequest{} // avoid memory leak
	*h = old[0 : n-1]
	return x
}

// shaperStream is linked only while it has pending requests. Idle nodes are
// reused within this session, with bounded retained heap storage.
type shaperStream struct {
	sid        uint32
	heap       shaperHeap
	prev, next *shaperStream
}

type shaperQueue struct {
	streams map[uint32]*shaperStream
	next    *shaperStream
	free    [16]*shaperStream
	freeLen int
	count   int
	mu      sync.Mutex
}

func NewShaperQueue() *shaperQueue {
	return &shaperQueue{streams: make(map[uint32]*shaperStream)}
}

func (h *shaperHeap) pushRequest(req writeRequest) {
	*h = append(*h, req)
	for i := len(*h) - 1; i > 0; {
		parent := (i - 1) / 2
		if !h.Less(i, parent) {
			break
		}
		h.Swap(i, parent)
		i = parent
	}
}

func (h *shaperHeap) popRequest() writeRequest {
	last := len(*h) - 1
	result := (*h)[0]
	(*h)[0] = (*h)[last]
	(*h)[last] = writeRequest{}
	*h = (*h)[:last]
	for i := 0; i*2+1 < last; {
		child := i*2 + 1
		if child+1 < last && h.Less(child+1, child) {
			child++
		}
		if !h.Less(child, i) {
			break
		}
		h.Swap(child, i)
		i = child
	}
	return result
}

func (sq *shaperQueue) Push(req writeRequest) {
	sq.mu.Lock()
	defer sq.mu.Unlock()
	sid := req.frame.sid
	node := sq.streams[sid]
	if node == nil {
		if sq.freeLen > 0 {
			sq.freeLen--
			node = sq.free[sq.freeLen]
			sq.free[sq.freeLen] = nil
		} else {
			node = new(shaperStream)
		}
		node.sid = sid
		sq.streams[sid] = node
		if sq.next == nil {
			node.prev, node.next = node, node
			sq.next = node
		} else {
			node.prev, node.next = sq.next.prev, sq.next
			node.prev.next, sq.next.prev = node, node
		}
	}
	node.heap.pushRequest(req)
	sq.count++
}

func (sq *shaperQueue) Pop() (writeRequest, bool) {
	sq.mu.Lock()
	defer sq.mu.Unlock()
	node := sq.next
	if node == nil {
		return writeRequest{}, false
	}
	req := node.heap.popRequest()
	sq.count--
	sq.next = node.next
	if len(node.heap) == 0 {
		delete(sq.streams, node.sid)
		if node.next == node {
			sq.next = nil
		} else {
			node.prev.next, node.next.prev = node.next, node.prev
		}
		node.prev, node.next = nil, nil
		node.sid = 0
		if cap(node.heap) > 64 {
			node.heap = nil
		}
		if sq.freeLen < len(sq.free) {
			sq.free[sq.freeLen] = node
			sq.freeLen++
		}
	}
	return req, true
}

// IsEmpty checks if the shaperQueue is empty.
func (sq *shaperQueue) IsEmpty() bool {
	sq.mu.Lock()
	defer sq.mu.Unlock()
	return sq.count == 0
}

// Len returns the total number of writeRequests in the shaperQueue.
func (sq *shaperQueue) Len() int {
	sq.mu.Lock()
	defer sq.mu.Unlock()
	return sq.count
}

