package deadline

import (
	"sync"
	"time"
)

// PipeDeadline is an abstraction for handling timeouts.
type PipeDeadline struct {
	mu          sync.Mutex // Guards timer, its active state, and cancel
	timer       *time.Timer
	timerActive bool
	stopped     bool
	cancel      chan struct{} // Must be non-nil
}

func MakePipeDeadline() PipeDeadline {
	return PipeDeadline{cancel: make(chan struct{})}
}

// Set sets the point in time when the deadline will time out.
// A timeout event is signaled by closing the channel returned by waiter.
// Once a timeout has occurred, the deadline can be refreshed by specifying a
// t value in the future.
//
// A zero value for t prevents timeout.
func (d *PipeDeadline) Set(t time.Time) {
	d.mu.Lock()
	defer d.mu.Unlock()

	if d.stopped {
		return
	}
	d.stopTimer()

	// Time is zero, then there is no deadline.
	closed := isClosedChan(d.cancel)
	if t.IsZero() {
		if closed {
			d.cancel = make(chan struct{})
		}
		return
	}

	// Time in the future, setup a timer to cancel in the future.
	if dur := time.Until(t); dur > 0 {
		if closed {
			d.cancel = make(chan struct{})
		}
		if d.timer == nil {
			d.timer = time.AfterFunc(dur, func() { close(d.cancel) })
		} else {
			d.timer.Reset(dur)
		}
		d.timerActive = true
		return
	}

	// Time in the past, so close immediately.
	if !closed {
		close(d.cancel)
	}
}

// stopTimer runs with mu held. A previously cleared deadline has an inactive
// timer and an open cancel channel; waiting on that channel would deadlock.
func (d *PipeDeadline) stopTimer() {
	if d.timerActive && !d.timer.Stop() {
		<-d.cancel // The callback finishes before Set can replace cancel.
	}
	d.timerActive = false
}

// stop prevents both existing and concurrently refreshed timers from retaining
// a closed connection. The connection itself wakes its blocked readers.
func (d *PipeDeadline) stop() {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.stopped = true
	d.stopTimer()
	d.timer = nil
}

// Wait returns a channel that is closed when the deadline is exceeded.
func (d *PipeDeadline) Wait() chan struct{} {
	d.mu.Lock()
	defer d.mu.Unlock()
	return d.cancel
}

func isClosedChan(c <-chan struct{}) bool {
	select {
	case <-c:
		return true
	default:
		return false
	}
}

func makeFilledChan() chan struct{} {
	ch := make(chan struct{}, 1)
	ch <- struct{}{}
	return ch
}

package packetbatch

import (
	"io"
	"net"

	"github.com/metacubex/sing/common/buf"
	N "github.com/metacubex/sing/common/network"
)

// VectorWriter reuses the iovec descriptors for a serialized connection writer.
// It consumes every input buffer. Only standard stream sockets use writev;
// protocol wrappers keep their explicit counted method or their ordinary Write.
// Calls must be serialized by the owning protocol's write lock.
type VectorWriter struct {
	writer  io.Writer
	counted N.VectorisedWriterWithCount
	native  bool
	inline  [4][]byte
	storage net.Buffers
	vectors net.Buffers
}

func NewVectorWriter(writer io.Writer) *VectorWriter {
	w := new(VectorWriter)
	w.Reset(writer)
	return w
}

// Reset changes the output while retaining scratch storage. It must run under
// the same owner lock as writes, including when a protocol replaces a wrapper.
func (w *VectorWriter) Reset(writer io.Writer) {
	w.writer, w.counted, w.native = writer, nil, false
	if counted, ok := writer.(N.VectorisedWriterWithCount); ok {
		w.counted = counted
	} else {
		switch writer.(type) {
		case *net.TCPConn, *net.UnixConn:
			w.native = true
		}
	}
}

func (w *VectorWriter) WriteVectorisedCount(buffers []*buf.Buffer) (int64, error) {
	if w.counted != nil {
		return w.counted.WriteVectorisedCount(buffers)
	}
	defer buf.ReleaseMulti(buffers)
	total := buf.LenMulti(buffers)
	var written int64
	var err error
	if w.native {
		if w.storage == nil {
			w.storage = w.inline[:]
		}
		if len(buffers) > len(w.storage) {
			w.storage = make(net.Buffers, len(buffers))
		}
		for i, buffer := range buffers {
			w.storage[i] = buffer.Bytes()
		}
		w.vectors = w.storage[:len(buffers)]
		written, err = w.vectors.WriteTo(w.writer)
		// WriteTo advances the slice and its elements. Clear the original span
		// as well, so neither successful nor failed writes retain payloads.
		clear(w.storage[:len(buffers)])
		w.vectors = nil
	} else {
		var data []byte
		if len(buffers) == 1 {
			data = buffers[0].Bytes()
		} else if total > 0 {
			data = buf.Get(total)
			if data != nil {
				defer buf.Put(data)
			} else {
				data = make([]byte, total)
			}
			buf.CopyMulti(data, buffers)
		}
		n, writeErr := w.writer.Write(data)
		written, err = int64(n), writeErr
	}
	if written < 0 || written > int64(total) {
		return 0, io.ErrShortWrite
	}
	if written != int64(total) && err == nil {
		err = io.ErrShortWrite
	}
	return written, err
}

package bufio

import (
	"io"
	"net"
	"sync"

	"github.com/metacubex/sing/common/buf"
	N "github.com/metacubex/sing/common/network"
)

// NewVectorisedWriterWithCount never infers progress from an error-only writer
// or unwraps a protocol. Standard sockets retain net.Buffers' native writev path;
// other writers receive one joined Write, whose byte count preserves framing.
func NewVectorisedWriterWithCount(writer io.Writer) N.VectorisedWriterWithCount {
	if counted, ok := writer.(N.VectorisedWriterWithCount); ok {
		return counted
	}
	switch writer.(type) {
	case *net.TCPConn, *net.UnixConn:
		return &countedNetVectorisedWriter{writer: writer}
	default:
		return &BufferedVectorisedWriter{upstream: writer}
	}
}

type countedNetVectorisedWriter struct {
	writer  io.Writer
	access  sync.Mutex
	inline  [4][]byte
	storage net.Buffers
	vectors net.Buffers
}

func (w *countedNetVectorisedWriter) WriteVectorisedCount(buffers []*buf.Buffer) (int64, error) {
	defer buf.ReleaseMulti(buffers)
	total := int64(buf.LenMulti(buffers))
	// A counted writer may be called concurrently just like its net.Conn.
	// Serialize only its reusable descriptor storage and the associated write.
	w.access.Lock()
	defer w.access.Unlock()
	if w.storage == nil {
		w.storage = w.inline[:]
	}
	if len(buffers) > len(w.storage) {
		w.storage = make(net.Buffers, len(buffers))
	}
	for i, buffer := range buffers {
		w.storage[i] = buffer.Bytes()
	}
	w.vectors = w.storage[:len(buffers)]
	n, err := w.vectors.WriteTo(w.writer)
	// net.Buffers advances its slice and elements, including on partial writes.
	// Clear the original span so no consumed payload remains reachable here.
	for i := range buffers {
		w.storage[i] = nil
	}
	w.vectors = nil
	return checkVectorisedCount(n, total, err)
}

func (w *BufferedVectorisedWriter) WriteVectorisedCount(buffers []*buf.Buffer) (int64, error) {
	defer buf.ReleaseMulti(buffers)
	total := buf.LenMulti(buffers)
	var data []byte
	if len(buffers) == 1 {
		data = buffers[0].Bytes()
	} else if total > 0 {
		data = buf.Get(total)
		if data != nil {
			defer buf.Put(data)
		} else {
			data = make([]byte, total)
		}
		buf.CopyMulti(data, buffers)
	}
	n, err := w.upstream.Write(data)
	return checkVectorisedCount(int64(n), int64(total), err)
}

func checkVectorisedCount(written, total int64, err error) (int64, error) {
	if written < 0 || written > total {
		return 0, io.ErrShortWrite
	}
	if written != total && err == nil {
		err = io.ErrShortWrite
	}
	return written, err
}

