package smux

import (
	"encoding/binary"
	"errors"
	"io"
	"net"
	"runtime"
	"sync"
	"sync/atomic"
	"time"

	"github.com/metacubex/sing/common/bufio"
	"github.com/metacubex/sing/common/network"
)

const (
	defaultAcceptBacklog = 1024
	minShaperNotifySize  = 16
	maxShaperSize        = 1024
	openCloseTimeout     = 30 * time.Second // Timeout for opening/closing streams
)

// CLASSID represents the class of a frame
type CLASSID int

const (
	CLSCTRL CLASSID = iota // prioritized control signal
	CLSDATA
)

// timeoutError representing timeouts for operations such as accept, read and write
//
// To better cooperate with the standard library, timeoutError should implement the standard library's `net.Error`.
//
// For example, using smux to implement net.Listener and work with http.Server, the keep-alive connection (*smux.Stream) will be unexpectedly closed.
// For more details, see https://github.com/xtaci/smux/pull/99.
type timeoutError struct{}

func (timeoutError) Error() string   { return "timeout" }
func (timeoutError) Temporary() bool { return true }
func (timeoutError) Timeout() bool   { return true }

var (
	ErrInvalidProtocol           = errors.New("invalid protocol")
	ErrConsumed                  = errors.New("peer consumed more than sent")
	ErrGoAway                    = errors.New("stream id overflows, should start a new connection")
	ErrTimeout         net.Error = &timeoutError{}
	ErrWouldBlock                = errors.New("operation would block on IO")
)

// writeRequest represents a request to write a frame
type writeRequest struct {
	class  CLASSID
	frame  Frame
	seq    uint32
	result chan writeResult
}

// writeResult represents the result of a write request
type writeResult struct {
	n   int
	err error
}

// Session defines a multiplexed connection for streams
type Session struct {
	conn io.ReadWriteCloser

	config           *Config
	goAway           int32  // flag id exhausted
	nextStreamID     uint32 // next stream identifier
	nextStreamIDLock sync.Mutex

	bucket       int32         // token bucket
	bucketNotify chan struct{} // used for waiting for tokens

	streams    map[uint32]*stream // all streams in this session
	streamLock sync.Mutex         // locks streams

	die     chan struct{} // flag session has died
	dieOnce sync.Once

	// socket error handling
	socketReadError      atomic.Value
	socketWriteError     atomic.Value
	chSocketReadError    chan struct{}
	chSocketWriteError   chan struct{}
	socketReadErrorOnce  sync.Once
	socketWriteErrorOnce sync.Once

	// smux protocol errors
	protoError     atomic.Value
	chProtoError   chan struct{}
	protoErrorOnce sync.Once

	chAccepts chan *stream

	sessionIsActive int32        // flag session is active
	acceptDeadline  atomic.Value // deadline for Accept()

	requestID        uint32            // Monotonic increasing write request ID
	shaper           chan writeRequest // a shaper for writing
	sq               *shaperQueue
	chShaperPending  chan struct{}
	chShaperConsumed chan struct{}
}

func newSession(config *Config, conn io.ReadWriteCloser, client bool) *Session {
	s := new(Session)
	s.die = make(chan struct{})
	s.conn = conn
	s.config = config
	s.streams = make(map[uint32]*stream)
	s.chAccepts = make(chan *stream, defaultAcceptBacklog)
	s.bucket = int32(config.MaxReceiveBuffer)
	s.bucketNotify = make(chan struct{}, 1)
	s.shaper = make(chan writeRequest, maxShaperSize)
	s.chSocketReadError = make(chan struct{})
	s.chSocketWriteError = make(chan struct{})
	s.chProtoError = make(chan struct{})
	s.chShaperPending = make(chan struct{}, 1)
	s.chShaperConsumed = make(chan struct{}, 1)
	s.sq = NewShaperQueue()

	if client {
		s.nextStreamID = 1
	} else {
		s.nextStreamID = 0
	}

	go s.shaperLoop()
	go s.recvLoop()
	go s.sendLoop()
	if !config.KeepAliveDisabled {
		go s.keepalive()
	}
	return s
}

// OpenStream is used to create a new stream
func (s *Session) OpenStream() (*Stream, error) {
	if s.IsClosed() {
		return nil, io.ErrClosedPipe
	}

	// generate stream id
	s.nextStreamIDLock.Lock()
	if s.goAway > 0 {
		s.nextStreamIDLock.Unlock()
		return nil, ErrGoAway
	}

	// check for stream id overflow
	if s.nextStreamID+2 < s.nextStreamID {
		s.goAway = 1
		s.nextStreamIDLock.Unlock()
		return nil, ErrGoAway
	}

	// allocate next stream id
	s.nextStreamID += 2
	sid := s.nextStreamID
	s.nextStreamIDLock.Unlock()

	stream := newStream(sid, s.config.MaxFrameSize, s)

	if _, err := s.writeControlFrame(newFrame(byte(s.config.Version), cmdSYN, sid)); err != nil {
		return nil, err
	}

	s.streamLock.Lock()
	defer s.streamLock.Unlock()
	select {
	case <-s.chSocketReadError:
		return nil, s.socketReadError.Load().(error)
	case <-s.chSocketWriteError:
		return nil, s.socketWriteError.Load().(error)
	case <-s.die:
		return nil, io.ErrClosedPipe
	default:
		s.streams[sid] = stream
		wrapper := &Stream{stream: stream}
		// NOTE(x): disabled finalizer for issue #997
		/*
			runtime.SetFinalizer(wrapper, func(s *Stream) {
				s.Close()
			})
		*/
		return wrapper, nil
	}
}

// Open returns a generic ReadWriteCloser
func (s *Session) Open() (io.ReadWriteCloser, error) {
	return s.OpenStream()
}

// AcceptStream is used to block until the next available stream
// is ready to be accepted.
func (s *Session) AcceptStream() (*Stream, error) {
	var deadline <-chan time.Time
	if d, ok := s.acceptDeadline.Load().(time.Time); ok && !d.IsZero() {
		timer := time.NewTimer(time.Until(d))
		defer timer.Stop()
		deadline = timer.C
	}

	select {
	case stream := <-s.chAccepts:
		wrapper := &Stream{stream: stream}
		runtime.SetFinalizer(wrapper, func(s *Stream) {
			s.Close()
		})
		return wrapper, nil
	case <-deadline:
		return nil, ErrTimeout
	case <-s.chSocketReadError:
		return nil, s.socketReadError.Load().(error)
	case <-s.chProtoError:
		return nil, s.protoError.Load().(error)
	case <-s.die:
		return nil, io.ErrClosedPipe
	}
}

// Accept Returns a generic ReadWriteCloser instead of smux.Stream
func (s *Session) Accept() (io.ReadWriteCloser, error) {
	return s.AcceptStream()
}

// Close is used to close the session and all streams.
func (s *Session) Close() error {
	var once bool
	s.dieOnce.Do(func() {
		close(s.die)
		once = true
	})

	if !once {
		return io.ErrClosedPipe
	}

	s.streamLock.Lock()
	for k := range s.streams {
		s.streams[k].sessionClose()
	}
	s.streamLock.Unlock()
	return s.conn.Close()
}

// CloseChan can be used by someone who wants to be notified immediately when this
// session is closed
func (s *Session) CloseChan() <-chan struct{} {
	return s.die
}

// notifyBucket notifies recvLoop that bucket is available
func (s *Session) notifyBucket() {
	select {
	case s.bucketNotify <- struct{}{}:
	default:
	}
}

func (s *Session) notifyReadError(err error) {
	s.socketReadErrorOnce.Do(func() {
		s.socketReadError.Store(err)
		close(s.chSocketReadError)
	})
}

func (s *Session) notifyWriteError(err error) {
	s.socketWriteErrorOnce.Do(func() {
		s.socketWriteError.Store(err)
		close(s.chSocketWriteError)
	})
}

func (s *Session) notifyProtoError(err error) {
	s.protoErrorOnce.Do(func() {
		s.protoError.Store(err)
		close(s.chProtoError)
	})
}

// IsClosed does a safe check to see if we have shutdown
func (s *Session) IsClosed() bool {
	select {
	case <-s.die:
		return true
	case <-s.chSocketReadError:
		return true
	case <-s.chSocketWriteError:
		return true
	case <-s.chProtoError:
		return true
	default:
		return false
	}
}

// NumStreams returns the number of currently open streams
func (s *Session) NumStreams() int {
	if s.IsClosed() {
		return 0
	}
	s.streamLock.Lock()
	defer s.streamLock.Unlock()
	return len(s.streams)
}

// SetDeadline sets a deadline used by Accept* calls.
// A zero time value disables the deadline.
func (s *Session) SetDeadline(t time.Time) error {
	s.acceptDeadline.Store(t)
	return nil
}

// LocalAddr satisfies net.Conn interface
func (s *Session) LocalAddr() net.Addr {
	if ts, ok := s.conn.(interface {
		LocalAddr() net.Addr
	}); ok {
		return ts.LocalAddr()
	}
	return nil
}

// RemoteAddr satisfies net.Conn interface
func (s *Session) RemoteAddr() net.Addr {
	if ts, ok := s.conn.(interface {
		RemoteAddr() net.Addr
	}); ok {
		return ts.RemoteAddr()
	}
	return nil
}

// notify the session that a stream has closed
func (s *Session) streamClosed(sid uint32) {
	s.streamLock.Lock()
	defer s.streamLock.Unlock()

	stream, ok := s.streams[sid]
	if !ok {
		return
	}

	if n := stream.recycleTokens(); n > 0 {
		// return remaining tokens to the bucket
		if atomic.AddInt32(&s.bucket, int32(n)) > 0 {
			s.notifyBucket()
		}
	}
	delete(s.streams, sid)
}

// returnTokens is called by stream to return token after read
func (s *Session) returnTokens(n int) {
	if atomic.AddInt32(&s.bucket, int32(n)) > 0 {
		s.notifyBucket()
	}
}

// recvLoop keeps on reading from underlying connection if tokens are available
func (s *Session) recvLoop() {
	var hdr rawHeader
	var updHdr updHeader

	for {
		// Wait until we have tokens or session is closed.
		for atomic.LoadInt32(&s.bucket) <= 0 && !s.IsClosed() {
			select {
			case <-s.bucketNotify:
			case <-s.die:
				// If it returns here, Accept() and OpenStream() are unblocked with io.ErrClosedPipe,
				// causing recvLoop to exit gracefully. If recvLoop is blocked in io.ReadFull, however,
				// it will be unblocked by a socket read error instead.
				return
			}
		}

		// As long as we have tokens, try to read frames.
		// read header first
		_, err := io.ReadFull(s.conn, hdr[:])
		if err != nil {
			s.notifyReadError(err)
			return
		}

		// Mark the session as active
		atomic.StoreInt32(&s.sessionIsActive, 1)

		// validate protocol version
		if hdr.Version() != byte(s.config.Version) {
			s.notifyProtoError(ErrInvalidProtocol)
			return
		}

		// handle different command types
		sid := hdr.StreamID()
		switch hdr.Cmd() {
		case cmdNOP:
		case cmdSYN: // stream opening
			var accepted *stream
			s.streamLock.Lock()
			if _, ok := s.streams[sid]; !ok {
				stream := newStream(sid, s.config.MaxFrameSize, s)
				s.streams[sid] = stream
				accepted = stream
			}
			s.streamLock.Unlock()

			if accepted != nil {
				select {
				case s.chAccepts <- accepted:
				case <-s.die:
				}
			}

		case cmdFIN: // stream closing
			s.streamLock.Lock()
			if stream, ok := s.streams[sid]; ok {
				stream.fin() // fin unblocks the readers and writers
			}
			s.streamLock.Unlock()

		case cmdPSH: // data frame
			if hdr.Length() == 0 {
				continue
			}

			// read payload from the underlying connection
			pNewbuf := defaultAllocator.Get(int(hdr.Length()))
			written, err := io.ReadFull(s.conn, *pNewbuf)
			if err != nil {
				s.notifyReadError(err)

				// recycle the buffer immediately.
				defaultAllocator.Put(pNewbuf)
				return
			}

			// push data to the corresponding stream
			s.streamLock.Lock()
			if stream, ok := s.streams[sid]; ok {
				stream.pushBytes(pNewbuf)
				// deduct tokens from the bucket
				atomic.AddInt32(&s.bucket, -int32(written))
				stream.wakeupReader()
			} else {
				// data directed to a missing/closed stream, recycle the buffer immediately.
				defaultAllocator.Put(pNewbuf)
			}
			s.streamLock.Unlock()

		case cmdUPD: // a window update signal
			_, err := io.ReadFull(s.conn, updHdr[:])
			if err != nil {
				s.notifyReadError(err)
				return
			}

			// update the window size for the corresponding stream
			s.streamLock.Lock()
			if stream, ok := s.streams[sid]; ok {
				stream.update(updHdr.Consumed(), updHdr.Window())
			}
			s.streamLock.Unlock()

		default:
			s.notifyProtoError(ErrInvalidProtocol)
			return
		}
	}
}

// keepalive sends NOP frames periodically to keep the connection alive
func (s *Session) keepalive() {
	tickerPing := time.NewTicker(s.config.KeepAliveInterval)
	tickerTimeout := time.NewTicker(s.config.KeepAliveTimeout)
	defer tickerPing.Stop()
	defer tickerTimeout.Stop()
	for {
		select {
		case <-tickerPing.C:
			s.writeFrameInternal(newFrame(byte(s.config.Version), cmdNOP, 0), tickerPing.C, CLSCTRL)
			s.notifyBucket() // force a wakeup signal to the recvLoop
		case <-tickerTimeout.C:
			if !atomic.CompareAndSwapInt32(&s.sessionIsActive, 1, 0) {
				// recvLoop may block while bucket is 0, in this case,
				// session should not be closed.
				if atomic.LoadInt32(&s.bucket) > 0 {
					s.Close()
					return
				}
			}
		case <-s.die:
			return
		}
	}
}

// shaperLoop implements a priority queue and bandwidth shaping for write requests.
// Eg: Control messages are prioritized over data messages, and shaper tries
// it's best to keep fair bandwidth among streams.
func (s *Session) shaperLoop() {
	chShaper := s.shaper

	for {
		select {
		case <-s.die:
			return
		case r := <-chShaper:
			s.sq.Push(r)
			// notify sendLoop there are pending requests
			if len(chShaper) == 0 || s.sq.Len() > minShaperNotifySize {
				s.notifyShaperPending()
			}

			if s.sq.Len() >= maxShaperSize {
				// stop accepting new requests temporarily if shaper queue is full
				chShaper = nil
			}
		case <-s.chShaperConsumed:
			// re-enable shaper channel
			chShaper = s.shaper
		}
	}
}

// notifyShaperPending notifies sendLoop that there are pending requests
func (s *Session) notifyShaperPending() {
	select {
	case s.chShaperPending <- struct{}{}:
	default:
	}
}

// notifyShaperConsumed notifies when shaper queue is being consumed
func (s *Session) notifyShaperConsumed() {
	select {
	case s.chShaperConsumed <- struct{}{}:
	default:
	}
}

type WriteBuffers interface {
	WriteBuffers(v [][]byte) (n int, err error)
}

func createWriteBuffers(conn interface{}) (WriteBuffers, bool) {
	if bw, ok := conn.(WriteBuffers); ok {
		return bw, true
	}
	switch socket := conn.(type) {
	case *net.TCPConn:
		return &netWriteBuffers{writer: socket}, true
	case *net.UnixConn:
		return &netWriteBuffers{writer: socket}, true
	}
	if bw, ok := bufio.CreateVectorisedWriter(conn); ok {
		return singWriteBuffers{bw}, true
	}
	return nil, false
}

// Used only by the session's send loop. WriteTo mutates its vector, so retain
// separate storage and refill it before each write.
type netWriteBuffers struct {
	writer  io.Writer
	inline  [2][]byte
	storage net.Buffers
	vectors net.Buffers
}

func (w *netWriteBuffers) WriteBuffers(vec [][]byte) (int, error) {
	if w.storage == nil {
		w.storage = w.inline[:]
	}
	if len(vec) > len(w.storage) {
		w.storage = make(net.Buffers, len(vec))
	}
	total := 0
	for i, data := range vec {
		w.storage[i] = data
		total += len(data)
	}
	w.vectors = w.storage[:len(vec)]
	n, err := w.vectors.WriteTo(w.writer)
	for i := range vec {
		w.storage[i] = nil
	}
	w.vectors = nil
	if err == nil && n != int64(total) {
		err = io.ErrShortWrite
	}
	return int(n), err
}

type singWriteBuffers struct {
	network.VectorisedWriter
}

func (s singWriteBuffers) WriteBuffers(vec [][]byte) (n int, err error) {
	return bufio.WriteVectorised(s.VectorisedWriter, vec)
}

// sendLoop sends frames over the underlying connection
func (s *Session) sendLoop() {
	var buf []byte
	var n int
	var err error
	var vec [][]byte // vector for writeBuffers

	bw, ok := createWriteBuffers(s.conn)

	if ok {
		buf = make([]byte, headerSize)
		vec = make([][]byte, 2)
	} else {
		buf = make([]byte, (1<<16)+headerSize)
	}

EVENT_LOOP:
	for {
		select {
		case <-s.die:
			return
		case <-s.chShaperPending:
			for {
				request, ok := s.sq.Pop()
				if !ok {
					// notify shaperLoop to accept new requests
					s.notifyShaperConsumed()
					goto EVENT_LOOP
				}

				buf[0] = request.frame.ver
				buf[1] = request.frame.cmd
				binary.LittleEndian.PutUint16(buf[2:], uint16(len(request.frame.data)))
				binary.LittleEndian.PutUint32(buf[4:], request.frame.sid)

				// support for scatter-gather I/O
				if len(vec) > 0 {
					vec[0] = buf[:headerSize]
					vec[1] = request.frame.data
					n, err = bw.WriteBuffers(vec)
				} else {
					copy(buf[headerSize:], request.frame.data)
					n, err = s.conn.Write(buf[:headerSize+len(request.frame.data)])
				}

				n -= headerSize
				if n < 0 {
					n = 0
				}

				result := writeResult{
					n:   n,
					err: err,
				}

				request.result <- result
				close(request.result)

				// store conn error
				if err != nil {
					s.notifyWriteError(err)
					return
				}
			}
		}
	}
}

// writeControlFrame writes the control frame to the underlying connection
// and returns the number of bytes written if successful
func (s *Session) writeControlFrame(f Frame) (n int, err error) {
	timer := time.NewTimer(openCloseTimeout)
	defer timer.Stop()

	return s.writeFrameInternal(f, timer.C, CLSCTRL)
}

// internal writeFrame version to support deadline used in keepalive
func (s *Session) writeFrameInternal(f Frame, deadline <-chan time.Time, class CLASSID) (int, error) {
	req := writeRequest{
		class:  class,
		frame:  f,
		seq:    atomic.AddUint32(&s.requestID, 1),
		result: make(chan writeResult, 1),
	}
	select {
	case s.shaper <- req:
	case <-s.die:
		return 0, io.ErrClosedPipe
	case <-s.chSocketWriteError:
		return 0, s.socketWriteError.Load().(error)
	case <-deadline:
		return 0, ErrTimeout
	}

	select {
	case result := <-req.result:
		return result.n, result.err
	case <-s.die:
		return 0, io.ErrClosedPipe
	case <-s.chSocketWriteError:
		return 0, s.socketWriteError.Load().(error)
	case <-deadline:
		return 0, ErrTimeout
	}
}

package packet

import (
	"io"
	"net"

	"github.com/metacubex/mihomo/constant/features"
	"github.com/metacubex/sing/common/buf"
	"github.com/metacubex/sing/common/bufio"
	M "github.com/metacubex/sing/common/metadata"
	N "github.com/metacubex/sing/common/network"
)

const maxPacketSize = 65535

// Reader adapts bounded read batches to one owned packet at a time. Reads and
// Close must be serialized; the owner closes the source first to interrupt I/O.
// Each returned buffer belongs to the caller, including empty datagrams.
type Reader struct {
	source       N.PacketReader
	options      N.ReadWaitOptions
	batch        N.PacketBatchReadWaiter
	connected    N.ConnectedPacketBatchReadWaiter
	single       N.PacketReadWaiter
	needCopy     bool
	buffers      []*buf.Buffer
	destinations []M.Socksaddr
	destination  M.Socksaddr
	offset       int
	closed       bool
}

func NewReader(source N.PacketReader, options N.ReadWaitOptions) *Reader {
	// Preserve an advertised MTU; otherwise allow a full UDP datagram. Low
	// memory builds reduce read-ahead, not packet capacity.
	if options.MTU == 0 {
		options.MTU = maxPacketSize
	}
	options.BatchSize = 4
	if features.WithLowMemory {
		options.BatchSize = 1
	}
	r := &Reader{source: source, options: options}
	if options.BatchSize > 1 {
		if batch, ok := bufio.CreatePacketBatchReadWaiter(source); ok {
			r.batch = batch
			r.needCopy = batch.InitializeReadWaiter(options)
			return r
		}
		if batch, ok := bufio.CreateConnectedPacketBatchReadWaiter(source); ok {
			r.connected = batch
			r.needCopy = batch.InitializeReadWaiter(options)
			return r
		}
	}
	if single, ok := bufio.CreatePacketReadWaiter(source); ok {
		r.single = single
		r.needCopy = single.InitializeReadWaiter(options)
	}
	return r
}

func (r *Reader) ReadPacket() (*buf.Buffer, M.Socksaddr, error) {
	if r.closed {
		return nil, M.Socksaddr{}, net.ErrClosed
	}
	if r.batch != nil || r.connected != nil {
		if r.offset == len(r.buffers) {
			var err error
			r.offset = 0
			if r.batch != nil {
				r.buffers, r.destinations, err = r.batch.WaitReadPackets()
			} else {
				r.buffers, r.destination, err = r.connected.WaitReadConnectedPackets()
			}
			if err == nil && (len(r.buffers) == 0 || (r.batch != nil && len(r.buffers) != len(r.destinations))) {
				err = io.ErrNoProgress
			}
			if err != nil {
				r.releasePending()
				return nil, M.Socksaddr{}, err
			}
		}
		buffer := r.buffers[r.offset]
		destination := r.destination
		if r.batch != nil {
			destination = r.destinations[r.offset]
		}
		r.buffers[r.offset] = nil
		r.offset++
		if buffer == nil {
			return nil, M.Socksaddr{}, io.ErrNoProgress
		}
		if r.needCopy {
			buffer = r.options.Copy(buffer)
		}
		return buffer, destination, nil
	}
	var buffer *buf.Buffer
	var destination M.Socksaddr
	var err error
	if r.single != nil {
		buffer, destination, err = r.single.WaitReadPacket()
	} else {
		buffer = r.options.NewPacketBuffer()
		destination, err = r.source.ReadPacket(buffer)
		r.options.PostReturn(buffer)
	}
	if err != nil {
		buffer.Release()
		return nil, M.Socksaddr{}, err
	}
	if buffer == nil {
		return nil, M.Socksaddr{}, io.ErrNoProgress
	}
	if r.needCopy {
		buffer = r.options.Copy(buffer)
	}
	return buffer, destination, nil
}

func (r *Reader) releasePending() {
	for i := r.offset; i < len(r.buffers); i++ {
		r.buffers[i].Release()
		r.buffers[i] = nil
	}
	r.buffers, r.destinations, r.offset = nil, nil, 0
}

func (r *Reader) Close() {
	if r.closed {
		return
	}
	r.closed = true
	r.releasePending()
	for _, waiter := range []any{r.batch, r.connected, r.single} {
		if releaser, ok := waiter.(N.ReadWaiterReleaser); ok {
			releaser.ReleaseReadWaiter()
		}
	}
}

package tunnel

import (
	"context"
	"errors"
	"net"
	"net/netip"
	"sync"
	"time"

	"github.com/metacubex/mihomo/common/deque"
	N "github.com/metacubex/mihomo/common/net"
	C "github.com/metacubex/mihomo/constant"
	"github.com/metacubex/mihomo/constant/features"
	"github.com/metacubex/mihomo/log"
	"github.com/metacubex/sing/common/buf"
	"github.com/metacubex/sing/common/bufio"
	M "github.com/metacubex/sing/common/metadata"
	SN "github.com/metacubex/sing/common/network"
)

type packetSender struct {
	ctx       context.Context
	cancel    context.CancelFunc
	ready     chan struct{}
	queue     deque.Deque[C.PacketAdapter]
	sendMutex sync.Mutex

	// destination NAT mapping
	originToTarget map[packetDestination]netip.Addr
	targetToOrigin map[netip.Addr]netip.Addr
	mappingMutex   sync.RWMutex

	// Process is the sole owner of this scratch space. Reuse it across writes:
	// slices passed to an interface otherwise escape once per batch.
	buffers      [packetSendBatchSize]*buf.Buffer
	destinations [packetSendBatchSize]M.Socksaddr
}

type packetDestination struct {
	ip   netip.Addr
	host string
}

func destinationKey(metadata *C.Metadata) packetDestination {
	if metadata.Host != "" {
		return packetDestination{host: metadata.Host}
	}
	return packetDestination{ip: metadata.DstIP}
}

// newPacketSender returns a bounded, nonblocking packet sender.
// It ensures that packets can be sent sequentially and without blocking
func newPacketSender() C.PacketSender {
	ctx, cancel := context.WithCancel(context.Background())
	s := &packetSender{
		ctx:    ctx,
		cancel: cancel,
		ready:  make(chan struct{}, 1),

		originToTarget: make(map[packetDestination]netip.Addr),
		targetToOrigin: make(map[netip.Addr]netip.Addr),
	}
	s.queue.SetBaseCap(senderCapacity)
	s.queue.Grow(senderCapacity)
	return s
}

func (s *packetSender) AddMapping(originMetadata *C.Metadata, metadata *C.Metadata) {
	s.mappingMutex.Lock()
	defer s.mappingMutex.Unlock()
	originKey := destinationKey(originMetadata)
	originAddr := originMetadata.DstIP
	targetAddr := metadata.DstIP
	if addr := s.originToTarget[originKey]; !addr.IsValid() { // overwrite only if the record is illegal
		s.originToTarget[originKey] = targetAddr
	}
	if addr := s.targetToOrigin[targetAddr]; !addr.IsValid() { // overwrite only if the record is illegal
		s.targetToOrigin[targetAddr] = originAddr
	}
}

func (s *packetSender) RestoreReadFrom(addr netip.Addr) netip.Addr {
	s.mappingMutex.RLock()
	defer s.mappingMutex.RUnlock()
	if originAddr := s.targetToOrigin[addr]; originAddr.IsValid() {
		return originAddr
	}
	return addr
}

func (s *packetSender) packetAddress(pc C.PacketConn, packet C.PacketAdapter) netip.AddrPort {
	metadata := packet.Metadata()

	s.mappingMutex.RLock()
	targetAddr := s.originToTarget[destinationKey(metadata)]
	s.mappingMutex.RUnlock()

	if targetAddr.IsValid() {
		return netip.AddrPortFrom(targetAddr, metadata.DstPort)
	}

	originMetadata := metadata  // save origin metadata
	metadata = metadata.Clone() // don't modify PacketAdapter's metadata

	_ = preHandleMetadata(metadata) // error was pre-checked
	metadata = metadata.Pure()
	if metadata.Host != "" {
		// TODO: ResolveUDP may take a long time to block the Process loop
		//       but we want keep sequence sending so can't open a new goroutine
		if err := pc.ResolveUDP(s.ctx, metadata); err != nil {
			log.Warnln("[UDP] Resolve Ip error: %s", err)
			return netip.AddrPort{}
		}
	}

	if !metadata.DstIP.IsValid() {
		log.Warnln("[UDP] Destination ip not valid: %#v", metadata)
		return netip.AddrPort{}
	}
	s.AddMapping(originMetadata, metadata)
	return metadata.AddrPort()
}

func (s *packetSender) processPacket(pc C.PacketConn, packet C.PacketAdapter, writer SN.PacketBatchWriterWithCount) {
	defer packet.Drop()
	if addr := s.packetAddress(pc, packet); addr.IsValid() && s.ctx.Err() == nil {
		// A single owned packet benefits from the same buffer path without any
		// read-ahead, including in low-memory builds. Borrowed packets retain
		// their scalar WriteTo path.
		if owned, ok := packet.(C.PacketBuffer); ok && writer != nil {
			if buffer := owned.TakeBuffer(); buffer != nil {
				s.buffers[0] = SN.NewReadWaitOptions(nil, pc).Copy(buffer)
				s.destinations[0] = M.SocksaddrFromNetIP(addr)
				n, err := writer.WritePacketBatchCount(s.buffers[:1], s.destinations[:1])
				n, _ = bufio.CheckPacketBatchCount(n, 1, err)
				s.buffers[0], s.destinations[0] = nil, M.Socksaddr{}
				if n == 1 {
					_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))
				}
				return
			}
		}
		_ = handleUDPToRemote(packet, pc, net.UDPAddrFromAddrPort(addr))
	}
}

const packetSendBatchSize = 4

func (s *packetSender) Process(pc C.PacketConn, proxy C.WriteBackProxy) {
	writer, canBatch := N.CreatePacketBatchWriterWithCount(pc)
	if !canBatch {
		writer = nil
	}
	canBatch = canBatch && !features.WithLowMemory
	batchSize := 1
	if canBatch {
		batchSize = packetSendBatchSize
	}
	for {
		select {
		case <-s.ctx.Done():
			return
		case <-s.ready:
			var packets [packetSendBatchSize]C.PacketAdapter
			count := s.takePackets(packets[:batchSize])
			if count == 0 {
				continue
			}
			if s.ctx.Err() != nil {
				for _, packet := range packets[:count] {
					packet.Drop()
				}
				return
			}
			if count == 1 {
				first := packets[0]
				if proxy != nil {
					proxy.UpdateWriteBack(first)
				}
				s.processPacket(pc, first, writer)
				continue
			}
			s.processBatch(pc, proxy, writer, packets[:count])
		}
	}
}

func (s *packetSender) processBatch(pc C.PacketConn, proxy C.WriteBackProxy, writer SN.PacketBatchWriterWithCount, packets []C.PacketAdapter) {
	defer func() {
		for _, packet := range packets {
			packet.Drop()
		}
	}()
	buffers := s.buffers[:]
	destinations := s.destinations[:]
	pending := 0
	options := SN.NewReadWaitOptions(nil, pc)
	flush := func() {
		if pending == 0 {
			return
		}
		if s.ctx.Err() != nil {
			buf.ReleaseMulti(buffers[:pending])
		} else {
			n, err := writer.WritePacketBatchCount(buffers[:pending], destinations[:pending])
			n, _ = bufio.CheckPacketBatchCount(n, pending, err)
			if n > 0 {
				_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))
			}
		}
		clear(buffers[:pending])
		clear(destinations[:pending])
		pending = 0
	}
	defer flush()
	for _, packet := range packets {
		if s.ctx.Err() != nil {
			return
		}
		// Do not hold earlier packets behind resolution of a new destination.
		s.mappingMutex.RLock()
		mapped := s.originToTarget[destinationKey(packet.Metadata())].IsValid()
		s.mappingMutex.RUnlock()
		if !mapped {
			flush()
		}
		if proxy != nil {
			proxy.UpdateWriteBack(packet)
		}
		addr := s.packetAddress(pc, packet)
		if !addr.IsValid() {
			continue
		}
		if owned, ok := packet.(C.PacketBuffer); ok {
			buffers[pending] = owned.TakeBuffer()
		}
		if buffers[pending] == nil {
			data := packet.Data()
			if options.NeedHeadroom() {
				// A borrowed packet needs one owned copy, but no temporary
				// buf.As descriptor before allocating its destination buffer.
				buffer := options.NewBufferSize(len(data))
				_, _ = buffer.Write(data)
				buffers[pending] = buffer
			} else {
				buffers[pending] = buf.As(data)
			}
		} else {
			buffers[pending] = options.Copy(buffers[pending])
		}
		destinations[pending] = M.SocksaddrFromNetIP(addr)
		pending++
	}
}

func (s *packetSender) dropAll() {
	for {
		var packets [packetSendBatchSize]C.PacketAdapter
		n := s.takePackets(packets[:])
		if n == 0 {
			return
		}
		for _, packet := range packets[:n] {
			packet.Drop()
		}
	}
}

// takePackets transfers ownership in FIFO order under one admission lock. A
// single wakeup represents all queued packets; rearm it only if work remains.
func (s *packetSender) takePackets(packets []C.PacketAdapter) int {
	s.sendMutex.Lock()
	defer s.sendMutex.Unlock()
	n := min(len(packets), s.queue.Len())
	for i := 0; i < n; i++ {
		packets[i] = s.queue.PopFront()
	}
	if s.queue.Len() > 0 {
		s.notify()
	}
	return n
}

func (s *packetSender) notify() {
	select {
	case s.ready <- struct{}{}:
	default:
	}
}

func (s *packetSender) Send(packet C.PacketAdapter) {
	s.sendMutex.Lock()
	if s.ctx.Err() == nil && s.queue.Len() < senderCapacity {
		s.queue.PushBack(packet)
		if s.queue.Len() == 1 {
			s.notify()
		}
		s.sendMutex.Unlock()
		return
	}
	s.sendMutex.Unlock()
	packet.Drop()
}

func (s *packetSender) Close() {
	s.sendMutex.Lock()
	s.cancel()
	s.sendMutex.Unlock()
	// After cancellation no sender can enqueue. Release callbacks run outside
	// the admission lock, so a callback may safely close or send again.
	s.dropAll()
}

func (s *packetSender) DoSniff(metadata *C.Metadata) error { return nil }

func handleUDPToRemote(packet C.UDPPacket, pc C.PacketConn, addr *net.UDPAddr) error {
	if addr == nil {
		return errors.New("udp addr invalid")
	}

	if _, err := pc.WriteTo(packet.Data(), addr); err != nil {
		return err
	}
	// reset timeout
	_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))

	return nil
}

func handleUDPToLocal(writeBack C.WriteBack, pc C.PacketConn, sender C.PacketSender, key string, oAddrPort netip.AddrPort) {
	defer func() { sender.Close(); _ = pc.Close(); closeAllLocalCoon(key); natTable.Delete(key) }()
	for {
		_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))
		data, put, addr, err := pc.WaitReadFrom()
		if err != nil {
			if put != nil {
				put()
			}
			return
		}
		var from M.Socksaddr
		if udp, ok := addr.(*net.UDPAddr); ok {
			if udp != nil {
				from = M.SocksaddrFromNetIP(udp.AddrPort())
			}
		} else {
			from = M.SocksaddrFromNet(addr)
		}
		if !from.IsIP() {
			log.Warnln("server returned an invalid UDP source (%s), force replace to (%s)", from, oAddrPort)
			from = M.SocksaddrFromNetIP(oAddrPort)
		}
		from.Addr = sender.RestoreReadFrom(from.Addr.Unmap()).Unmap()
		from.Fqdn = ""
		size := len(data)
		n, err := writeBack.WriteBack(data, from.UDPAddr())
		if put != nil {
			put()
		}
		if err != nil || n != size {
			return
		}
	}
}

func closeAllLocalCoon(lAddr string) {
	natTable.RangeForLocalConn(lAddr, func(key string, value *net.UDPConn) bool {
		conn := value

		conn.Close()
		log.Debugln("Closing TProxy local conn... lAddr=%s rAddr=%s", lAddr, key)
		return true
	})
}

func handleSocket(inbound, outbound net.Conn) {
	N.Relay(inbound, outbound)
}

package packet

import (
	"io"
	"net"

	"github.com/metacubex/mihomo/constant/features"
	"github.com/metacubex/sing/common/buf"
	"github.com/metacubex/sing/common/bufio"
	M "github.com/metacubex/sing/common/metadata"
	N "github.com/metacubex/sing/common/network"
)

const maxPacketSize = 65535

// Reader adapts bounded read batches to one owned packet at a time. Reads and
// Close must be serialized; the owner closes the source first to interrupt I/O.
// Each returned buffer belongs to the caller, including empty datagrams.
type Reader struct {
	source       N.PacketReader
	options      N.ReadWaitOptions
	batch        N.PacketBatchReadWaiter
	connected    N.ConnectedPacketBatchReadWaiter
	single       N.PacketReadWaiter
	needCopy     bool
	buffers      []*buf.Buffer
	destinations []M.Socksaddr
	destination  M.Socksaddr
	offset       int
	closed       bool
}

func NewReader(source N.PacketReader, options N.ReadWaitOptions) *Reader {
	// Preserve an advertised MTU; otherwise allow a full UDP datagram. Low
	// memory builds reduce read-ahead, not packet capacity.
	if options.MTU == 0 {
		options.MTU = maxPacketSize
	}
	options.BatchSize = 4
	if features.WithLowMemory {
		options.BatchSize = 1
	}
	r := &Reader{source: source, options: options}
	if options.BatchSize > 1 {
		if batch, ok := bufio.CreatePacketBatchReadWaiter(source); ok {
			r.batch = batch
			r.needCopy = batch.InitializeReadWaiter(options)
			return r
		}
		if batch, ok := bufio.CreateConnectedPacketBatchReadWaiter(source); ok {
			r.connected = batch
			r.needCopy = batch.InitializeReadWaiter(options)
			return r
		}
	}
	if single, ok := bufio.CreatePacketReadWaiter(source); ok {
		r.single = single
		r.needCopy = single.InitializeReadWaiter(options)
	}
	return r
}

func (r *Reader) ReadPacket() (*buf.Buffer, M.Socksaddr, error) {
	if r.closed {
		return nil, M.Socksaddr{}, net.ErrClosed
	}
	if r.batch != nil || r.connected != nil {
		if r.offset == len(r.buffers) {
			var err error
			r.offset = 0
			if r.batch != nil {
				r.buffers, r.destinations, err = r.batch.WaitReadPackets()
			} else {
				r.buffers, r.destination, err = r.connected.WaitReadConnectedPackets()
			}
			if err == nil && (len(r.buffers) == 0 || (r.batch != nil && len(r.buffers) != len(r.destinations))) {
				err = io.ErrNoProgress
			}
			if err != nil {
				r.releasePending()
				return nil, M.Socksaddr{}, err
			}
		}
		buffer := r.buffers[r.offset]
		destination := r.destination
		if r.batch != nil {
			destination = r.destinations[r.offset]
		}
		r.buffers[r.offset] = nil
		r.offset++
		if buffer == nil {
			return nil, M.Socksaddr{}, io.ErrNoProgress
		}
		if r.needCopy {
			buffer = r.options.Copy(buffer)
		}
		return buffer, destination, nil
	}
	var buffer *buf.Buffer
	var destination M.Socksaddr
	var err error
	if r.single != nil {
		buffer, destination, err = r.single.WaitReadPacket()
	} else {
		buffer = r.options.NewPacketBuffer()
		destination, err = r.source.ReadPacket(buffer)
		r.options.PostReturn(buffer)
	}
	if err != nil {
		buffer.Release()
		return nil, M.Socksaddr{}, err
	}
	if buffer == nil {
		return nil, M.Socksaddr{}, io.ErrNoProgress
	}
	if r.needCopy {
		buffer = r.options.Copy(buffer)
	}
	return buffer, destination, nil
}

func (r *Reader) releasePending() {
	for i := r.offset; i < len(r.buffers); i++ {
		r.buffers[i].Release()
		r.buffers[i] = nil
	}
	r.buffers, r.destinations, r.offset = nil, nil, 0
}

func (r *Reader) Close() {
	if r.closed {
		return
	}
	r.closed = true
	r.releasePending()
	for _, waiter := range []any{r.batch, r.connected, r.single} {
		if releaser, ok := waiter.(N.ReadWaiterReleaser); ok {
			releaser.ReleaseReadWaiter()
		}
	}
}

package tunnel

import (
	"context"
	"errors"
	"net"
	"net/netip"
	"sync"
	"time"

	"github.com/metacubex/mihomo/common/deque"
	N "github.com/metacubex/mihomo/common/net"
	C "github.com/metacubex/mihomo/constant"
	"github.com/metacubex/mihomo/constant/features"
	"github.com/metacubex/mihomo/log"
	"github.com/metacubex/sing/common/buf"
	"github.com/metacubex/sing/common/bufio"
	M "github.com/metacubex/sing/common/metadata"
	SN "github.com/metacubex/sing/common/network"
)

type packetSender struct {
	ctx       context.Context
	cancel    context.CancelFunc
	ready     chan struct{}
	queue     deque.Deque[C.PacketAdapter]
	sendMutex sync.Mutex

	// destination NAT mapping
	originToTarget map[packetDestination]netip.Addr
	targetToOrigin map[netip.Addr]netip.Addr
	mappingMutex   sync.RWMutex

	// Process is the sole owner of this scratch space. Reuse it across writes:
	// slices passed to an interface otherwise escape once per batch.
	buffers      [packetSendBatchSize]*buf.Buffer
	destinations [packetSendBatchSize]M.Socksaddr
}

type packetDestination struct {
	ip   netip.Addr
	host string
}

func destinationKey(metadata *C.Metadata) packetDestination {
	if metadata.Host != "" {
		return packetDestination{host: metadata.Host}
	}
	return packetDestination{ip: metadata.DstIP}
}

// newPacketSender returns a bounded, nonblocking packet sender.
// It ensures that packets can be sent sequentially and without blocking
func newPacketSender() C.PacketSender {
	ctx, cancel := context.WithCancel(context.Background())
	s := &packetSender{
		ctx:    ctx,
		cancel: cancel,
		ready:  make(chan struct{}, 1),

		originToTarget: make(map[packetDestination]netip.Addr),
		targetToOrigin: make(map[netip.Addr]netip.Addr),
	}
	s.queue.SetBaseCap(senderCapacity)
	s.queue.Grow(senderCapacity)
	return s
}

func (s *packetSender) AddMapping(originMetadata *C.Metadata, metadata *C.Metadata) {
	s.mappingMutex.Lock()
	defer s.mappingMutex.Unlock()
	originKey := destinationKey(originMetadata)
	originAddr := originMetadata.DstIP
	targetAddr := metadata.DstIP
	if addr := s.originToTarget[originKey]; !addr.IsValid() { // overwrite only if the record is illegal
		s.originToTarget[originKey] = targetAddr
	}
	if addr := s.targetToOrigin[targetAddr]; !addr.IsValid() { // overwrite only if the record is illegal
		s.targetToOrigin[targetAddr] = originAddr
	}
}

func (s *packetSender) RestoreReadFrom(addr netip.Addr) netip.Addr {
	s.mappingMutex.RLock()
	defer s.mappingMutex.RUnlock()
	if originAddr := s.targetToOrigin[addr]; originAddr.IsValid() {
		return originAddr
	}
	return addr
}

func (s *packetSender) packetAddress(pc C.PacketConn, packet C.PacketAdapter) netip.AddrPort {
	metadata := packet.Metadata()

	s.mappingMutex.RLock()
	targetAddr := s.originToTarget[destinationKey(metadata)]
	s.mappingMutex.RUnlock()

	if targetAddr.IsValid() {
		return netip.AddrPortFrom(targetAddr, metadata.DstPort)
	}

	originMetadata := metadata  // save origin metadata
	metadata = metadata.Clone() // don't modify PacketAdapter's metadata

	_ = preHandleMetadata(metadata) // error was pre-checked
	metadata = metadata.Pure()
	if metadata.Host != "" {
		// TODO: ResolveUDP may take a long time to block the Process loop
		//       but we want keep sequence sending so can't open a new goroutine
		if err := pc.ResolveUDP(s.ctx, metadata); err != nil {
			log.Warnln("[UDP] Resolve Ip error: %s", err)
			return netip.AddrPort{}
		}
	}

	if !metadata.DstIP.IsValid() {
		log.Warnln("[UDP] Destination ip not valid: %#v", metadata)
		return netip.AddrPort{}
	}
	s.AddMapping(originMetadata, metadata)
	return metadata.AddrPort()
}

func (s *packetSender) processPacket(pc C.PacketConn, packet C.PacketAdapter, writer SN.PacketBatchWriterWithCount) {
	defer packet.Drop()
	if addr := s.packetAddress(pc, packet); addr.IsValid() && s.ctx.Err() == nil {
		// A single owned packet benefits from the same buffer path without any
		// read-ahead, including in low-memory builds. Borrowed packets retain
		// their scalar WriteTo path.
		if owned, ok := packet.(C.PacketBuffer); ok && writer != nil {
			if buffer := owned.TakeBuffer(); buffer != nil {
				s.buffers[0] = SN.NewReadWaitOptions(nil, pc).Copy(buffer)
				s.destinations[0] = M.SocksaddrFromNetIP(addr)
				n, err := writer.WritePacketBatchCount(s.buffers[:1], s.destinations[:1])
				n, _ = bufio.CheckPacketBatchCount(n, 1, err)
				s.buffers[0], s.destinations[0] = nil, M.Socksaddr{}
				if n == 1 {
					_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))
				}
				return
			}
		}
		_ = handleUDPToRemote(packet, pc, net.UDPAddrFromAddrPort(addr))
	}
}

const packetSendBatchSize = 4

func (s *packetSender) Process(pc C.PacketConn, proxy C.WriteBackProxy) {
	writer, canBatch := N.CreatePacketBatchWriterWithCount(pc)
	if !canBatch {
		writer = nil
	}
	canBatch = canBatch && !features.WithLowMemory
	batchSize := 1
	if canBatch {
		batchSize = packetSendBatchSize
	}
	for {
		select {
		case <-s.ctx.Done():
			return
		case <-s.ready:
			var packets [packetSendBatchSize]C.PacketAdapter
			count := s.takePackets(packets[:batchSize])
			if count == 0 {
				continue
			}
			if s.ctx.Err() != nil {
				for _, packet := range packets[:count] {
					packet.Drop()
				}
				return
			}
			if count == 1 {
				first := packets[0]
				if proxy != nil {
					proxy.UpdateWriteBack(first)
				}
				s.processPacket(pc, first, writer)
				continue
			}
			s.processBatch(pc, proxy, writer, packets[:count])
		}
	}
}

func (s *packetSender) processBatch(pc C.PacketConn, proxy C.WriteBackProxy, writer SN.PacketBatchWriterWithCount, packets []C.PacketAdapter) {
	defer func() {
		for _, packet := range packets {
			packet.Drop()
		}
	}()
	buffers := s.buffers[:]
	destinations := s.destinations[:]
	pending := 0
	options := SN.NewReadWaitOptions(nil, pc)
	flush := func() {
		if pending == 0 {
			return
		}
		if s.ctx.Err() != nil {
			buf.ReleaseMulti(buffers[:pending])
		} else {
			n, err := writer.WritePacketBatchCount(buffers[:pending], destinations[:pending])
			n, _ = bufio.CheckPacketBatchCount(n, pending, err)
			if n > 0 {
				_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))
			}
		}
		clear(buffers[:pending])
		clear(destinations[:pending])
		pending = 0
	}
	defer flush()
	for _, packet := range packets {
		if s.ctx.Err() != nil {
			return
		}
		// Do not hold earlier packets behind resolution of a new destination.
		s.mappingMutex.RLock()
		mapped := s.originToTarget[destinationKey(packet.Metadata())].IsValid()
		s.mappingMutex.RUnlock()
		if !mapped {
			flush()
		}
		if proxy != nil {
			proxy.UpdateWriteBack(packet)
		}
		addr := s.packetAddress(pc, packet)
		if !addr.IsValid() {
			continue
		}
		if owned, ok := packet.(C.PacketBuffer); ok {
			buffers[pending] = owned.TakeBuffer()
		}
		if buffers[pending] == nil {
			data := packet.Data()
			if options.NeedHeadroom() {
				// A borrowed packet needs one owned copy, but no temporary
				// buf.As descriptor before allocating its destination buffer.
				buffer := options.NewBufferSize(len(data))
				_, _ = buffer.Write(data)
				buffers[pending] = buffer
			} else {
				buffers[pending] = buf.As(data)
			}
		} else {
			buffers[pending] = options.Copy(buffers[pending])
		}
		destinations[pending] = M.SocksaddrFromNetIP(addr)
		pending++
	}
}

func (s *packetSender) dropAll() {
	for {
		var packets [packetSendBatchSize]C.PacketAdapter
		n := s.takePackets(packets[:])
		if n == 0 {
			return
		}
		for _, packet := range packets[:n] {
			packet.Drop()
		}
	}
}

// takePackets transfers ownership in FIFO order under one admission lock. A
// single wakeup represents all queued packets; rearm it only if work remains.
func (s *packetSender) takePackets(packets []C.PacketAdapter) int {
	s.sendMutex.Lock()
	defer s.sendMutex.Unlock()
	n := min(len(packets), s.queue.Len())
	for i := 0; i < n; i++ {
		packets[i] = s.queue.PopFront()
	}
	if s.queue.Len() > 0 {
		s.notify()
	}
	return n
}

func (s *packetSender) notify() {
	select {
	case s.ready <- struct{}{}:
	default:
	}
}

func (s *packetSender) Send(packet C.PacketAdapter) {
	s.sendMutex.Lock()
	if s.ctx.Err() == nil && s.queue.Len() < senderCapacity {
		s.queue.PushBack(packet)
		if s.queue.Len() == 1 {
			s.notify()
		}
		s.sendMutex.Unlock()
		return
	}
	s.sendMutex.Unlock()
	packet.Drop()
}

func (s *packetSender) Close() {
	s.sendMutex.Lock()
	s.cancel()
	s.sendMutex.Unlock()
	// After cancellation no sender can enqueue. Release callbacks run outside
	// the admission lock, so a callback may safely close or send again.
	s.dropAll()
}

func (s *packetSender) DoSniff(metadata *C.Metadata) error { return nil }

func handleUDPToRemote(packet C.UDPPacket, pc C.PacketConn, addr *net.UDPAddr) error {
	if addr == nil {
		return errors.New("udp addr invalid")
	}

	if _, err := pc.WriteTo(packet.Data(), addr); err != nil {
		return err
	}
	// reset timeout
	_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))

	return nil
}

func handleUDPToLocal(writeBack C.WriteBack, pc C.PacketConn, sender C.PacketSender, key string, oAddrPort netip.AddrPort) {
	defer func() { sender.Close(); _ = pc.Close(); closeAllLocalCoon(key); natTable.Delete(key) }()
	for {
		_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))
		data, put, addr, err := pc.WaitReadFrom()
		if err != nil {
			if put != nil {
				put()
			}
			return
		}
		var from M.Socksaddr
		if udp, ok := addr.(*net.UDPAddr); ok {
			if udp != nil {
				from = M.SocksaddrFromNetIP(udp.AddrPort())
			}
		} else {
			from = M.SocksaddrFromNet(addr)
		}
		if !from.IsIP() {
			log.Warnln("server returned an invalid UDP source (%s), force replace to (%s)", from, oAddrPort)
			from = M.SocksaddrFromNetIP(oAddrPort)
		}
		from.Addr = sender.RestoreReadFrom(from.Addr.Unmap()).Unmap()
		from.Fqdn = ""
		size := len(data)
		n, err := writeBack.WriteBack(data, from.UDPAddr())
		if put != nil {
			put()
		}
		if err != nil || n != size {
			return
		}
	}
}

func closeAllLocalCoon(lAddr string) {
	natTable.RangeForLocalConn(lAddr, func(key string, value *net.UDPConn) bool {
		conn := value

		conn.Close()
		log.Debugln("Closing TProxy local conn... lAddr=%s rAddr=%s", lAddr, key)
		return true
	})
}

func handleSocket(inbound, outbound net.Conn) {
	N.Relay(inbound, outbound)
}

package packet

import (
	"io"
	"net"
	"runtime"

	"github.com/metacubex/sing/common/buf"
	M "github.com/metacubex/sing/common/metadata"
)

// BufferReader transfers one owned packet, preserving any available headroom.
// It shares all prefetched packets with the connection's other read APIs.
// On error it releases its storage and returns a nil buffer.
type BufferReader interface {
	ReadPacketBuffer() (*buf.Buffer, M.Socksaddr, error)
}

// ReadPacketBuffer uses only an explicit capability. The legacy fallback copies
// before releasing borrowed bytes; it never unwraps a pending-packet owner.
func ReadPacketBuffer(conn EnhancePacketConn) (*buf.Buffer, M.Socksaddr, error) {
	if reader, ok := conn.(BufferReader); ok {
		return reader.ReadPacketBuffer()
	}
	data, put, addr, err := conn.WaitReadFrom()
	if put != nil {
		defer put()
	}
	if err != nil {
		return nil, M.Socksaddr{}, err
	}
	buffer := buf.NewSize(len(data))
	_, _ = buffer.Write(data)
	return buffer, ownedPacketSource(addr), nil
}

func (c *enhancePacketConn) ReadPacketBuffer() (*buf.Buffer, M.Socksaddr, error) {
	// Preserve a protocol's explicit owned reader, including its own caches.
	if reader, ok := c.PacketConn.(BufferReader); ok {
		return reader.ReadPacketBuffer()
	}
	buffer := buf.NewSize(maxPacketSize)
	n, addr, err := c.PacketConn.ReadFrom(buffer.FreeBytes())
	if err != nil {
		buffer.Release()
		return nil, M.Socksaddr{}, err
	}
	buffer.Resize(0, n)
	return buffer, ownedPacketSource(addr), nil
}

func (c *enhanceUDPConn) ReadPacketBuffer() (*buf.Buffer, M.Socksaddr, error) {
	return c.readState.read(c.source)
}

func (c *enhanceSingPacketConn) ReadPacketBuffer() (*buf.Buffer, M.Socksaddr, error) {
	return c.readState.read(c.SingPacketConn)
}

func (c *refPacketConn) ReadPacketBuffer() (*buf.Buffer, M.Socksaddr, error) {
	defer runtime.KeepAlive(c.ref)
	return ReadPacketBuffer(c.pc)
}

func (c *threadSafePacketConn) ReadPacketBuffer() (*buf.Buffer, M.Socksaddr, error) {
	return ReadPacketBuffer(c.EnhancePacketConn)
}

func (c *enhanceWithBufferPacketConn) ReadPacketBuffer() (*buf.Buffer, M.Socksaddr, error) {
	var buffer *buf.Buffer
	n, addr, err := c.ReadFromWithBuffer(func(sizeHint int) []byte {
		buffer.Release()
		buffer = buf.NewSize(sizeHint)
		return buffer.FreeBytes()
	})
	if err != nil {
		buffer.Release()
		return nil, M.Socksaddr{}, err
	}
	if buffer == nil {
		if n != 0 {
			return nil, M.Socksaddr{}, io.ErrNoProgress
		}
		buffer = buf.NewSize(0)
	}
	buffer.Resize(0, n)
	return buffer, ownedPacketSource(addr), nil
}

func ownedPacketSource(addr net.Addr) M.Socksaddr {
	if udp, ok := addr.(*net.UDPAddr); ok {
		if udp == nil {
			return M.Socksaddr{}
		}
		return M.SocksaddrFromNetIP(udp.AddrPort())
	}
	return M.SocksaddrFromNet(addr)
}

