		Protocol:    metadata.Type.String(),
		Source:      M.SocksaddrFrom(metadata.SrcIP, metadata.SrcPort),
		Destination: M.ParseSocksaddrHostPort(metadata.String(), metadata.DstPort),
	}
}

func NewListenerHandler(lc ListenerConfig) (h *ListenerHandler, err error) {
	h = &ListenerHandler{ListenerConfig: lc}
	h.handlerId = utils.NewUUIDV4()
	h.muxService, err = mux.NewService(mux.ServiceOptions{
		NewStreamContext: func(ctx context.Context, conn net.Conn) context.Context {
			return ctx
		},
		Logger:  log.SingInfoToDebugLogger, // convert sing-mux info log to debug
		Handler: h,
		Padding: lc.MuxOption.Padding,
		Brutal: mux.BrutalOptions{
			Enabled:    lc.MuxOption.Brutal.Enabled,
			SendBPS:    utils.StringToBps(lc.MuxOption.Brutal.Up),
			ReceiveBPS: utils.StringToBps(lc.MuxOption.Brutal.Down),
		},
	})
	return
}

func (h *ListenerHandler) IsSpecialFqdn(fqdn string) bool {
	switch fqdn {
	case mux.Destination.Fqdn,
		vmess.MuxDestination.Fqdn,
		uot.MagicAddress,
		uot.LegacyMagicAddress:
		return true
	default:
		return false
	}
}

func (h *ListenerHandler) ParseSpecialFqdn(ctx context.Context, conn net.Conn, metadata M.Metadata) error {
	switch metadata.Destination.Fqdn {
	case mux.Destination.Fqdn:
		return h.muxService.NewConnection(ctx, conn, UpstreamMetadata(metadata))
	case vmess.MuxDestination.Fqdn:
		return vmess.HandleMuxConnection(ctx, conn, metadata, h)
	case uot.MagicAddress:
		request, err := uot.ReadRequest(conn)
		if err != nil {
			return E.Cause(err, "read UoT request")
		}
		metadata.Destination = request.Destination
		return h.NewPacketConnection(ctx, uot.NewConn(conn, *request), metadata)
	case uot.LegacyMagicAddress:
		metadata.Destination = M.Socksaddr{Addr: netip.IPv4Unspecified()}
		return h.NewPacketConnection(ctx, uot.NewConn(conn, uot.Request{}), metadata)
	}
	return errors.New("not special fqdn")
}

func (h *ListenerHandler) NewConnection(ctx context.Context, conn net.Conn, metadata M.Metadata) error {
	if h.IsSpecialFqdn(metadata.Destination.Fqdn) {
		return h.ParseSpecialFqdn(ctx, conn, metadata)
	}

	if deadline.NeedAdditionalReadDeadline(conn) {
		conn = N.NewDeadlineConn(conn) // conn from sing should check NeedAdditionalReadDeadline
	}

	cMetadata := &C.Metadata{
		NetWork: C.TCP,
		Type:    h.Type,
	}
	if metadata.Source.IsIP() && metadata.Source.Fqdn == "" {
		cMetadata.RawSrcAddr = metadata.Source.Unwrap().TCPAddr()
	}
	if metadata.Destination.IsIP() && metadata.Destination.Fqdn == "" {
		cMetadata.RawDstAddr = metadata.Destination.Unwrap().TCPAddr()
	}
	inbound.ApplyAdditions(cMetadata, inbound.WithDstAddr(metadata.Destination), inbound.WithSrcAddr(metadata.Source), inbound.WithInAddr(conn.LocalAddr()))
	inbound.ApplyAdditions(cMetadata, h.Additions...)
	applyContextAdditions(ctx, cMetadata)

	h.Tunnel.HandleTCPConn(conn, cMetadata) // this goroutine must exit after conn unused
	return nil
}

func (h *ListenerHandler) NewPacketConnection(ctx context.Context, conn network.PacketConn, metadata M.Metadata) error {
	if metadata.Destination.Fqdn == packetaddr.SeqPacketMagicAddress {
		conn = packetaddr.NewConn(bufio.NewNetPacketConn(conn), M.Socksaddr{})
	}

	connID := utils.NewUUIDV4().String() // make a new SNAT key
	reply := &packetReply{writer: bufio.NewNetPacketWriter(conn), packetWriter: conn}
	rAddr := N.NewCustomAddr(h.Type.String(), connID, metadata.Source.UDPAddr())
	lAddr := conn.LocalAddr()
	if address := getInAddr(ctx); address != nil {
		lAddr = address
	}
	reader := P.NewReader(conn, network.ReadWaitOptions{})
	defer func() {
		_ = conn.Close() // interrupt an in-flight WriteBack before waiting for it
		reader.Close()
		reply.close()
	}()
	for {
		buff, dest, err := reader.ReadPacket()
		if err != nil {
			if ShouldIgnorePacketError(err) {
				break
			}
			return err
		}
		cPacket := &packet{
			reply: reply,
			rAddr: rAddr,
			lAddr: lAddr,
			buff:  buff,
		}
		h.handlePacket(ctx, cPacket, metadata.Source, dest)
	}
	return nil
}

type localAddr interface {
	LocalAddr() net.Addr
}

func (h *ListenerHandler) NewPacket(ctx context.Context, key netip.AddrPort, buffer *buf.Buffer, metadata M.Metadata, init func(natConn network.PacketConn) network.PacketWriter) {
	packetWriter := init(nil)
	writer := bufio.NewNetPacketWriter(packetWriter)
	cPacket := &packet{
		reply: &packetReply{writer: writer, packetWriter: packetWriter},
		rAddr: metadata.Source.UDPAddr(),
		buff:  buffer,
	}
	if h.Type != C.TUN { // make the handler-related SNAT key for not TUN listener
		connID := fmt.Sprintf("%s:%s", h.handlerId, key)
		cPacket.rAddr = N.NewCustomAddr(h.Type.String(), connID, cPacket.rAddr) // for tunnel's handleUDPConn
	}
	if conn, ok := common.Cast[localAddr](writer); ok { // tun does not have real inAddr
		cPacket.lAddr = conn.LocalAddr()
	}
	h.handlePacket(ctx, cPacket, metadata.Source, metadata.Destination)
}

func (h *ListenerHandler) handlePacket(ctx context.Context, cPacket *packet, source M.Socksaddr, destination M.Socksaddr) {
	cMetadata := &C.Metadata{
		NetWork: C.UDP,
		Type:    h.Type,
	}
	if source.IsIP() && source.Fqdn == "" {
		cMetadata.RawSrcAddr = source.Unwrap().UDPAddr()
	}
	if destination.IsIP() && destination.Fqdn == "" {
		cMetadata.RawDstAddr = destination.Unwrap().UDPAddr()
	}
	inbound.ApplyAdditions(cMetadata, inbound.WithDstAddr(destination), inbound.WithSrcAddr(source), inbound.WithInAddr(cPacket.InAddr()))
	inbound.ApplyAdditions(cMetadata, h.Additions...)
	applyContextAdditions(ctx, cMetadata)

	h.Tunnel.HandleUDPPacket(cPacket, cMetadata)
}

func (h *ListenerHandler) NewError(ctx context.Context, err error) {
	log.Warnln("%s listener get error: %+v", h.Type.String(), err)
}

func (h *ListenerHandler) TypeMutation(typ C.Type) *ListenerHandler {
	handler := *h
	handler.Type = typ
	return &handler
}

func ShouldIgnorePacketError(err error) bool {
	// ignore simple error
	if E.IsTimeout(err) || E.IsClosed(err) || E.IsCanceled(err) {
		return true
	}
	return false
}

type packet struct {
	reply *packetReply
	rAddr net.Addr
	lAddr net.Addr
	buff  *buf.Buffer
}

func (c *packet) Data() []byte {
	if c.buff == nil {
		return nil
	}
	return c.buff.Bytes()
}

func (c *packet) TakeBuffer() *buf.Buffer {
	buffer := c.buff
	c.buff = nil
	return buffer
}

// WriteBack wirtes UDP packet with source(ip, port) = `addr`
func (c *packet) WriteBack(b []byte, addr net.Addr) (n int, err error) {
	return c.reply.WriteBack(b, addr)
}

func (c *packet) WriteBackTarget() C.WriteBack { return c.reply }

// packetReply outlives any one payload/metadata pair. NAT stores this handle,
// while each packet owns only its payload and per-packet routing metadata.
type packetReply struct {
	mutex        sync.Mutex
	writer       network.NetPacketWriter
	packetWriter network.PacketWriter
}

func (c *packetReply) close() {
	c.mutex.Lock()
	defer c.mutex.Unlock()
	c.writer, c.packetWriter = nil, nil
}

func (c *packetReply) WriteBack(b []byte, addr net.Addr) (n int, err error) {
	if addr == nil {
		err = errors.New("address is invalid")
		return
	}

	c.mutex.Lock()
	defer c.mutex.Unlock()
	conn := c.writer
	if conn == nil {
		err = net.ErrClosed
		return
	}

	return conn.WriteTo(b, addr)
}

func (c *packetReply) WriteBackBuffer(buffer *buf.Buffer, destination M.Socksaddr) error {
	c.mutex.Lock()
	defer c.mutex.Unlock()
	if c.packetWriter == nil {
		buffer.Release()
		return net.ErrClosed
	}
	buffer = network.NewReadWaitOptions(nil, c.packetWriter).Copy(buffer)
	return c.packetWriter.WritePacket(buffer, destination)
}

// LocalAddr returns the source IP/Port of UDP Packet
func (c *packet) LocalAddr() net.Addr {
	return c.rAddr
}

func (c *packet) Drop() {
	c.buff.Release()
	c.buff = nil
}

func (c *packet) InAddr() net.Addr {
	return c.lAddr
}

package snell

import (
	"bufio"
	"context"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"net"
	"net/netip"
	"strings"
	"sync"
	"sync/atomic"

	"github.com/metacubex/mihomo/adapter/inbound"
	N "github.com/metacubex/mihomo/common/net"
	"github.com/metacubex/mihomo/common/utils"
	C "github.com/metacubex/mihomo/constant"
	LC "github.com/metacubex/mihomo/listener/config"
	"github.com/metacubex/mihomo/listener/jls"
	"github.com/metacubex/mihomo/listener/restls"
	"github.com/metacubex/mihomo/listener/shadowtls"
	"github.com/metacubex/mihomo/listener/sing"
	"github.com/metacubex/mihomo/transport/shadowsocks/shadowaead"
	obfs "github.com/metacubex/mihomo/transport/simple-obfs"
	"github.com/metacubex/mihomo/transport/snell"

	"github.com/metacubex/sing/common/buf"
	M "github.com/metacubex/sing/common/metadata"
	SS "github.com/sagernet/sing-snell"
)

type Listener struct {
	closed    atomic.Bool
	config    LC.SnellServer
	listeners []net.Listener
	ctx       context.Context
	cancel    context.CancelFunc
	service   SS.Service
	handler   *sing.ListenerHandler
}

func New(config LC.SnellServer, lc C.InboundListenConfig, tunnel C.Tunnel, additions ...inbound.Addition) (C.MultiAddrListener, error) {
	if config.Version == 0 {
		config.Version = snell.Version4
	}
	switch config.Version {
	case snell.Version1, snell.Version2, snell.Version3, snell.Version4, snell.Version5, snell.Version6:
	default:
		return nil, fmt.Errorf("snell inbound version %d is not supported", config.Version)
	}
	if config.Psk == "" {
		return nil, errors.New("snell inbound requires psk")
	}
	if config.Version6Mode != "" && config.Version != snell.Version6 {
		return nil, errors.New("snell version6-mode requires version 6")
	}
	switch config.ObfsMode {
	case "", "http", "tls":
	default:
		return nil, fmt.Errorf("snell inbound obfs mode error: %s", config.ObfsMode)
	}

	securityModes := make([]string, 0, 3)
	if config.ShadowTLS.Enable {
		securityModes = append(securityModes, "shadow-tls")
	}
	if config.ResTLS.Enable {
		securityModes = append(securityModes, "res-tls")
	}
	if config.JLSConfig.Enable {
		securityModes = append(securityModes, "jls")
	}
	if len(securityModes) > 1 {
		return nil, errors.New("security modes are mutually exclusive: " + strings.Join(securityModes, ", "))
	}

	var shadowTLSBuilder *shadowtls.Builder
	if config.ShadowTLS.Enable {
		var err error
		shadowTLSBuilder, err = shadowtls.New(config.ShadowTLS, tunnel)
		if err != nil {
			return nil, err
		}
	}
	var restlsBuilder *restls.Builder
	if config.ResTLS.Enable {
		restlsBuilder = restls.New(config.ResTLS, tunnel)
	}
	var jlsBuilder *jls.Builder
	if config.JLSConfig.Enable {
		var err error
		jlsBuilder, err = jls.New(config.JLSConfig, tunnel)
		if err != nil {
			return nil, err
		}
	}
	l := &Listener{config: config}
	l.ctx, l.cancel = context.WithCancel(context.Background())
	if config.Version >= snell.Version4 {
		if err := l.initSingSnell(tunnel); err != nil {
			l.cancel()
			return nil, err
		}
	}
	for _, addr := range strings.Split(config.Listen, ",") {
		addr = strings.TrimSpace(addr)
		if addr == "" {
			continue
		}
		ln, err := lc.Listen(context.Background(), "tcp", addr)
		if err != nil {
			_ = l.Close()
			return nil, err
		}
		if shadowTLSBuilder != nil {
			ln = shadowTLSBuilder.NewListener(ln)
		} else if restlsBuilder != nil {
			ln = restlsBuilder.NewListener(ln)
		} else if jlsBuilder != nil {
			ln = jlsBuilder.NewListener(ln)
		}
		l.listeners = append(l.listeners, ln)
		go func(ln net.Listener) {
			for {
				conn, err := ln.Accept()
				if err != nil {
					if l.closed.Load() {
						return
					}
					continue
				}
				go l.HandleConn(conn, tunnel, additions...)
			}
		}(ln)
	}
	return l, nil
}

func (l *Listener) Close() error {
	l.closed.Store(true)
	l.cancel()
	var retErr error
	for _, ln := range l.listeners {
		if err := ln.Close(); err != nil {
			retErr = err
		}
	}
	return retErr
}

func (l *Listener) Config() string {
	return l.config.String()
}

func (l *Listener) AddrList() (addrList []net.Addr) {
	for _, ln := range l.listeners {
		addrList = append(addrList, ln.Addr())
	}
	return
}

func (l *Listener) HandleConn(rawConn net.Conn, tunnel C.Tunnel, additions ...inbound.Addition) {
	defer rawConn.Close()
	stop := context.AfterFunc(l.ctx, func() { _ = rawConn.Close() })
	defer stop()
	user, loaded := shadowtls.UserFromConn(rawConn)
	if jlsUser, jlsLoaded := jls.UserFromConn(rawConn); jlsLoaded {
		user, loaded = jlsUser, true
	}
	if loaded {
		additions = append(append([]inbound.Addition(nil), additions...), inbound.WithInUser(user))
	}
	conn := rawConn
	if l.service != nil && l.config.Version < snell.Version6 {
		l.handleSingSnell(conn, additions...)
		return
	}
	switch l.config.ObfsMode {
	case "http":
		conn = obfs.NewHTTPObfsServer(conn)
	case "tls":
		conn = obfs.NewTLSObfsServer(conn)
	case "":
	default:
		return
	}
	if l.service != nil {
		l.handleSingSnell(conn, additions...)
		return
	}
	stream := snell.ServerStreamConn(conn, []byte(l.config.Psk), l.config.Version)
	for {
		reuse, err := l.handleRequest(stream, tunnel, additions...)
		if err != nil || !reuse {
			return
		}
	}
}

func (l *Listener) handleSingSnell(conn net.Conn, additions ...inbound.Addition) {
	ctx := sing.WithAdditions(l.ctx, additions...)
	ctx = sing.WithInAddr(ctx, conn.LocalAddr())
	err := l.service.NewConnection(ctx, conn, M.SocksaddrFromNet(conn.RemoteAddr()), nil)
	if err != nil && !isClosedError(err) {
		l.handler.NewError(ctx, err)
	}
}

func (l *Listener) handleRequest(stream *snell.Snell, tunnel C.Tunnel, additions ...inbound.Addition) (bool, error) {
	br := bufio.NewReader(stream)
	version, err := br.ReadByte()
	if err != nil {
		return false, err
	}
	if version != snell.Version {
		return false, fmt.Errorf("snell invalid protocol version: %d", version)
	}

	command, err := br.ReadByte()
	if err != nil {
		return false, err
	}
	if command == snell.CommandPing {
		_, _ = stream.Write([]byte{snell.CommandPong})
		return false, nil
	}

	clientID, err := readClientID(br)
	if err != nil {
		return false, err
	}

	switch command {
	case snell.CommandConnect, snell.CommandConnectV2:
		return l.handleTCP(stream, br, command == snell.CommandConnectV2, clientID, tunnel, additions...)
	case snell.CommandUDP:
		if !l.config.UDP {
			return false, errors.New("snell UDP is disabled")
		}
		return false, l.handleUDP(stream, clientID, tunnel, additions...)
	default:
		return false, fmt.Errorf("snell unknown command: %d", command)
	}
}

func readClientID(r *bufio.Reader) (string, error) {
	length, err := r.ReadByte()
	if err != nil {
		return "", err
	}
	if length == 0 {
		return "", nil
	}
	id := make([]byte, int(length))
	if _, err := io.ReadFull(r, id); err != nil {
		return "", err
	}
	return string(id), nil
}

func (l *Listener) handleTCP(stream *snell.Snell, br *bufio.Reader, reuse bool, clientID string, tunnel C.Tunnel, additions ...inbound.Addition) (bool, error) {
	hostLen, err := br.ReadByte()
	if err != nil {
		return false, err
	}
	if hostLen == 0 {
		return false, errors.New("snell connect host is empty")
	}

	hostBytes := make([]byte, int(hostLen))
	if _, err := io.ReadFull(br, hostBytes); err != nil {
		return false, err
	}
	var portBytes [2]byte
	if _, err := io.ReadFull(br, portBytes[:]); err != nil {
		return false, err
	}

	metadata := l.metadata(C.TCP, string(hostBytes), binary.BigEndian.Uint16(portBytes[:]), stream, clientID, additions...)
	conn := &tcpRequestConn{
		Conn:   stream,
		reader: br,
		reuse:  reuse,
	}
	tunnel.HandleTCPConn(conn, metadata)
	if !reuse {
		return false, nil
	}
	return true, nil
}

func (l *Listener) handleUDP(stream *snell.Snell, clientID string, tunnel C.Tunnel, additions ...inbound.Addition) error {
	if _, err := stream.Write([]byte{snell.CommandTunnel}); err != nil {
		return err
	}

	connID := utils.NewUUIDV4().String()
	localAddr := N.NewCustomAddr(C.SNELL.String(), connID, stream.RemoteAddr())
	reply := &udpReply{conn: stream}
	for {
		buffer, err := stream.ReadPacketBuffer()
		if err != nil {
			if errors.Is(err, io.EOF) || errors.Is(err, shadowaead.ErrZeroChunk) {
				return nil
			}
			return err
		}
		request, err := snell.ParseUDPRequest(buffer.Bytes())
		if err != nil {
			buffer.Release()
			return err
		}
		metadata := l.metadata(C.UDP, request.Host, request.Port, stream, clientID, additions...)
		if request.Ip.IsValid() {
			metadata.Host = ""
			metadata.DstIP = request.Ip
		}

		buffer.Advance(buffer.Len() - len(request.Payload))
		packet := &udpPacket{
			buffer:    buffer,
			reply:     reply,
			localAddr: localAddr,
			dstAddr:   metadata.AddrPort(),
		}
		tunnel.HandleUDPPacket(packet, metadata)
	}
}

func (l *Listener) metadata(network C.NetWork, host string, port uint16, conn net.Conn, clientID string, additions ...inbound.Addition) *C.Metadata {
	metadata := &C.Metadata{
		NetWork: network,
		Type:    C.SNELL,
		DstPort: port,
	}
	if ip, err := netip.ParseAddr(host); err == nil {
		metadata.DstIP = ip.Unmap()
	} else {
		metadata.Host = host
	}
	inbound.ApplyAdditions(metadata, inbound.WithSrcAddr(conn.RemoteAddr()), inbound.WithInAddr(conn.LocalAddr()))
	inbound.ApplyAdditions(metadata, additions...)
	if clientID != "" {
		inbound.ApplyAdditions(metadata, inbound.WithInUser(clientID))
	}
	return metadata
}

func writeCommandError(w io.Writer, code byte, message string) error {
	msg := []byte(message)
	if len(msg) > 255 {
		msg = msg[:255]
	}
	buf := make([]byte, 0, 3+len(msg))
	buf = append(buf, snell.CommandError, code, byte(len(msg)))
	buf = append(buf, msg...)
	_, err := w.Write(buf)
	return err
}

type tcpRequestConn struct {
	net.Conn
	reader       *bufio.Reader
	reuse        bool
	writeMu      sync.Mutex
	closeOnce    sync.Once
	replyWritten bool
}

func (c *tcpRequestConn) Read(p []byte) (int, error) {
	n, err := c.reader.Read(p)
	if errors.Is(err, shadowaead.ErrZeroChunk) {
		err = io.EOF
	}
	return n, err
}

func (c *tcpRequestConn) Write(p []byte) (int, error) {
	c.writeMu.Lock()
	defer c.writeMu.Unlock()

	if !c.replyWritten {
		payload := make([]byte, 1+len(p))
		payload[0] = snell.CommandTunnel
		copy(payload[1:], p)
		if _, err := c.Conn.Write(payload); err != nil {
			return 0, err
		}
		c.replyWritten = true
		return len(p), nil
	}
	return c.Conn.Write(p)
}

func (c *tcpRequestConn) CloseWrite() error {
	return c.Close()
}

func (c *tcpRequestConn) Close() error {
	var err error
	c.closeOnce.Do(func() {
		c.writeMu.Lock()
		defer c.writeMu.Unlock()

		if !c.replyWritten {
			err = writeCommandError(c.Conn, 0x65, "Remote EOF")
			if !c.reuse {
				err = errors.Join(err, c.Conn.Close())
			}
			return
		}
		if c.reuse {
			_, err = c.Conn.Write(nil)
			return
		}
		err = c.Conn.Close()
	})
	return err
}

type udpPacket struct {
	buffer    *buf.Buffer
	reply     *udpReply
	localAddr net.Addr
	dstAddr   netip.AddrPort
}

func (p *udpPacket) Data() []byte {
	if p.buffer == nil {
		return nil
	}
	return p.buffer.Bytes()
}

func (p *udpPacket) TakeBuffer() *buf.Buffer {
	buffer := p.buffer
	p.buffer = nil
	return buffer
}

func (p *udpPacket) WriteBack(b []byte, addr net.Addr) (int, error) {
	if addr == nil && p.dstAddr.IsValid() {
		addr = net.UDPAddrFromAddrPort(p.dstAddr)
	}
	return p.reply.WriteBack(b, addr)
}

func (p *udpPacket) WriteBackTarget() C.WriteBack { return p.reply }

func (p *udpPacket) DefaultWriteBackAddress() netip.AddrPort { return p.dstAddr }

type udpReply struct {
	conn    *snell.Snell
	writeMu sync.Mutex
}

func (r *udpReply) WriteBack(b []byte, addr net.Addr) (int, error) {
	r.writeMu.Lock()
	defer r.writeMu.Unlock()
	return snell.WritePacketResponse(r.conn, addr, b)
}

func (r *udpReply) WriteBackBuffer(buffer *buf.Buffer, destination M.Socksaddr) error {
	r.writeMu.Lock()
	defer r.writeMu.Unlock()
	return r.conn.WritePacketResponseBuffer(buffer, destination)
}

func (p *udpPacket) Drop() {
	p.buffer.Release()
	p.buffer = nil
}

func (p *udpPacket) LocalAddr() net.Addr {
	return p.localAddr
}

var _ C.MultiAddrListener = (*Listener)(nil)
var _ C.UDPPacket = (*udpPacket)(nil)

package statistic

import (
	"os"

	"github.com/metacubex/mihomo/common/net/packet"
	"github.com/metacubex/sing/common/buf"
	"github.com/metacubex/sing/common/bufio"
	M "github.com/metacubex/sing/common/metadata"
	N "github.com/metacubex/sing/common/network"
)

func (ut *udpTracker) ReadPacketBuffer() (*buf.Buffer, M.Socksaddr, error) {
	buffer, destination, err := packet.ReadPacketBuffer(ut.PacketConn)
	if err == nil {
		download := int64(buffer.Len())
		if ut.pushToManager {
			ut.manager.PushDownloaded(download)
		}
		ut.DownloadTotal.Add(download)
	}
	return buffer, destination, err
}

func (ut *udpTracker) CreatePacketBatchWriterWithCount() (N.PacketBatchWriterWithCount, bool) {
	writer, ok := packet.CreatePacketBatchWriterWithCount(ut.PacketConn)
	if !ok {
		return nil, false
	}
	return &udpBatchWriter{writer: writer, tracker: ut}, true
}

type udpBatchWriter struct {
	writer  N.PacketBatchWriterWithCount
	tracker *udpTracker
}

func (w *udpBatchWriter) WritePacketBatchCount(buffers []*buf.Buffer, destinations []M.Socksaddr) (int, error) {
	if len(buffers) == 0 || len(buffers) != len(destinations) {
		buf.ReleaseMulti(buffers)
		return 0, os.ErrInvalid
	}
	var inline [8]int
	lengths := inline[:min(len(buffers), len(inline))]
	if len(buffers) > len(inline) {
		lengths = make([]int, len(buffers))
	}
	for i, b := range buffers {
		lengths[i] = b.Len()
	}
	n, err := w.writer.WritePacketBatchCount(buffers, destinations)
	n, err = bufio.CheckPacketBatchCount(n, len(buffers), err)
	var uploaded int64
	for _, length := range lengths[:n] {
		uploaded += int64(length)
	}
	if w.tracker.pushToManager {
		w.tracker.manager.PushUploaded(uploaded)
	}
	w.tracker.UploadTotal.Add(uploaded)
	return n, err
}

package tunnel

import (
	"context"
	"errors"
	"net"
	"net/netip"
	"sync"
	"time"

	N "github.com/metacubex/mihomo/common/net"
	C "github.com/metacubex/mihomo/constant"
	"github.com/metacubex/mihomo/constant/features"
	"github.com/metacubex/mihomo/log"
	"github.com/metacubex/sing/common/buf"
	"github.com/metacubex/sing/common/bufio"
	M "github.com/metacubex/sing/common/metadata"
	SN "github.com/metacubex/sing/common/network"
)

type packetSender struct {
	ctx       context.Context
	cancel    context.CancelFunc
	queue     chan C.PacketAdapter
	sendMutex sync.Mutex

	// destination NAT mapping
	originToTarget map[packetDestination]netip.Addr
	targetToOrigin map[netip.Addr]netip.Addr
	mappingMutex   sync.RWMutex

	// Process is the sole owner of this scratch space. Reuse it across writes:
	// slices passed to an interface otherwise escape once per batch.
	buffers      [packetSendBatchSize]*buf.Buffer
	destinations [packetSendBatchSize]M.Socksaddr
}

type packetDestination struct {
	ip   netip.Addr
	host string
}

func destinationKey(metadata *C.Metadata) packetDestination {
	if metadata.Host != "" {
		return packetDestination{host: metadata.Host}
	}
	return packetDestination{ip: metadata.DstIP}
}

// newPacketSender returns a bounded, nonblocking packet sender.
// It ensures that packets can be sent sequentially and without blocking
func newPacketSender() C.PacketSender {
	ctx, cancel := context.WithCancel(context.Background())
	s := &packetSender{
		ctx:    ctx,
		cancel: cancel,
		queue:  make(chan C.PacketAdapter, senderCapacity),

		originToTarget: make(map[packetDestination]netip.Addr),
		targetToOrigin: make(map[netip.Addr]netip.Addr),
	}
	return s
}

func (s *packetSender) AddMapping(originMetadata *C.Metadata, metadata *C.Metadata) {
	s.mappingMutex.Lock()
	defer s.mappingMutex.Unlock()
	originKey := destinationKey(originMetadata)
	originAddr := originMetadata.DstIP
	targetAddr := metadata.DstIP
	if addr := s.originToTarget[originKey]; !addr.IsValid() { // overwrite only if the record is illegal
		s.originToTarget[originKey] = targetAddr
	}
	if addr := s.targetToOrigin[targetAddr]; !addr.IsValid() { // overwrite only if the record is illegal
		s.targetToOrigin[targetAddr] = originAddr
	}
}

func (s *packetSender) RestoreReadFrom(addr netip.Addr) netip.Addr {
	s.mappingMutex.RLock()
	defer s.mappingMutex.RUnlock()
	if originAddr := s.targetToOrigin[addr]; originAddr.IsValid() {
		return originAddr
	}
	return addr
}

func (s *packetSender) packetAddress(pc C.PacketConn, packet C.PacketAdapter) netip.AddrPort {
	metadata := packet.Metadata()

	s.mappingMutex.RLock()
	targetAddr := s.originToTarget[destinationKey(metadata)]
	s.mappingMutex.RUnlock()

	if targetAddr.IsValid() {
		return netip.AddrPortFrom(targetAddr, metadata.DstPort)
	}

	originMetadata := metadata  // save origin metadata
	metadata = metadata.Clone() // don't modify PacketAdapter's metadata

	_ = preHandleMetadata(metadata) // error was pre-checked
	metadata = metadata.Pure()
	if metadata.Host != "" {
		// TODO: ResolveUDP may take a long time to block the Process loop
		//       but we want keep sequence sending so can't open a new goroutine
		if err := pc.ResolveUDP(s.ctx, metadata); err != nil {
			log.Warnln("[UDP] Resolve Ip error: %s", err)
			return netip.AddrPort{}
		}
	}

	if !metadata.DstIP.IsValid() {
		log.Warnln("[UDP] Destination ip not valid: %#v", metadata)
		return netip.AddrPort{}
	}
	s.AddMapping(originMetadata, metadata)
	return metadata.AddrPort()
}

func (s *packetSender) processPacket(pc C.PacketConn, packet C.PacketAdapter, writer SN.PacketBatchWriterWithCount) {
	defer packet.Drop()
	if addr := s.packetAddress(pc, packet); addr.IsValid() && s.ctx.Err() == nil {
		// A single owned packet benefits from the same buffer path without any
		// read-ahead, including in low-memory builds. Borrowed packets retain
		// their scalar WriteTo path.
		if owned, ok := packet.(C.PacketBuffer); ok && writer != nil {
			if buffer := owned.TakeBuffer(); buffer != nil {
				s.buffers[0] = SN.NewReadWaitOptions(nil, pc).Copy(buffer)
				s.destinations[0] = M.SocksaddrFromNetIP(addr)
				n, err := writer.WritePacketBatchCount(s.buffers[:1], s.destinations[:1])
				n, _ = bufio.CheckPacketBatchCount(n, 1, err)
				s.buffers[0], s.destinations[0] = nil, M.Socksaddr{}
				if n == 1 {
					_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))
				}
				return
			}
		}
		_ = handleUDPToRemote(packet, pc, net.UDPAddrFromAddrPort(addr))
	}
}

const packetSendBatchSize = 4

func (s *packetSender) Process(pc C.PacketConn, proxy C.WriteBackProxy) {
	writer, canBatch := N.CreatePacketBatchWriterWithCount(pc)
	if !canBatch {
		writer = nil
	}
	canBatch = canBatch && !features.WithLowMemory
	batchSize := 1
	if canBatch {
		batchSize = packetSendBatchSize
	}
	for {
		select {
		case <-s.ctx.Done():
			return
		case first := <-s.queue:
			var packets [packetSendBatchSize]C.PacketAdapter
			packets[0] = first
			count := 1 + s.takePackets(packets[1:batchSize])
			if s.ctx.Err() != nil {
				for _, packet := range packets[:count] {
					packet.Drop()
				}
				return
			}
			if count == 1 {
				first := packets[0]
				if proxy != nil {
					proxy.UpdateWriteBack(first)
				}
				s.processPacket(pc, first, writer)
				continue
			}
			s.processBatch(pc, proxy, writer, packets[:count])
		}
	}
}

func (s *packetSender) processBatch(pc C.PacketConn, proxy C.WriteBackProxy, writer SN.PacketBatchWriterWithCount, packets []C.PacketAdapter) {
	defer func() {
		for _, packet := range packets {
			packet.Drop()
		}
	}()
	buffers := s.buffers[:]
	destinations := s.destinations[:]
	pending := 0
	options := SN.NewReadWaitOptions(nil, pc)
	flush := func() {
		if pending == 0 {
			return
		}
		if s.ctx.Err() != nil {
			buf.ReleaseMulti(buffers[:pending])
		} else {
			n, err := writer.WritePacketBatchCount(buffers[:pending], destinations[:pending])
			n, _ = bufio.CheckPacketBatchCount(n, pending, err)
			if n > 0 {
				_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))
			}
		}
		clear(buffers[:pending])
		clear(destinations[:pending])
		pending = 0
	}
	defer flush()
	for _, packet := range packets {
		if s.ctx.Err() != nil {
			return
		}
		// Do not hold earlier packets behind resolution of a new destination.
		s.mappingMutex.RLock()
		mapped := s.originToTarget[destinationKey(packet.Metadata())].IsValid()
		s.mappingMutex.RUnlock()
		if !mapped {
			flush()
		}
		if proxy != nil {
			proxy.UpdateWriteBack(packet)
		}
		addr := s.packetAddress(pc, packet)
		if !addr.IsValid() {
			continue
		}
		if owned, ok := packet.(C.PacketBuffer); ok {
			buffers[pending] = owned.TakeBuffer()
		}
		if buffers[pending] == nil {
			data := packet.Data()
			if options.NeedHeadroom() {
				// A borrowed packet needs one owned copy, but no temporary
				// buf.As descriptor before allocating its destination buffer.
				buffer := options.NewBufferSize(len(data))
				_, _ = buffer.Write(data)
				buffers[pending] = buffer
			} else {
				buffers[pending] = buf.As(data)
			}
		} else {
			buffers[pending] = options.Copy(buffers[pending])
		}
		destinations[pending] = M.SocksaddrFromNetIP(addr)
		pending++
	}
}

func (s *packetSender) dropAll() {
	for {
		var packets [packetSendBatchSize]C.PacketAdapter
		n := s.takePackets(packets[:])
		if n == 0 {
			return
		}
		for _, packet := range packets[:n] {
			packet.Drop()
		}
	}
}

// takePackets drains immediately available packets without waiting for a full batch.
func (s *packetSender) takePackets(packets []C.PacketAdapter) int {
	n := 0
	for n < len(packets) {
		select {
		case p := <-s.queue:
			packets[n] = p
			n++
		default:
			return n
		}
	}
	return n
}
func (s *packetSender) Send(packet C.PacketAdapter) {
	s.sendMutex.Lock()
	if s.ctx.Err() == nil {
		select {
		case s.queue <- packet:
			s.sendMutex.Unlock()
			return
		default:
		}
	}
	s.sendMutex.Unlock()
	packet.Drop()
}

func (s *packetSender) Close() {
	s.sendMutex.Lock()
	s.cancel()
	s.sendMutex.Unlock()
	// After cancellation no sender can enqueue. Release callbacks run outside
	// the admission lock, so a callback may safely close or send again.
	s.dropAll()
}

func (s *packetSender) DoSniff(metadata *C.Metadata) error { return nil }

func handleUDPToRemote(packet C.UDPPacket, pc C.PacketConn, addr *net.UDPAddr) error {
	if addr == nil {
		return errors.New("udp addr invalid")
	}

	if _, err := pc.WriteTo(packet.Data(), addr); err != nil {
		return err
	}
	// reset timeout
	_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))

	return nil
}

func handleUDPToLocal(writeBack C.WriteBack, pc C.PacketConn, sender C.PacketSender, key string, oAddrPort netip.AddrPort) {
	defer func() {
		sender.Close()
		_ = pc.Close()
		closeAllLocalCoon(key)
		natTable.Delete(key)
	}()

	for {
		_ = pc.SetReadDeadline(time.Now().Add(udpTimeout))
		buffer, from, err := N.ReadPacketBuffer(pc)
		if err != nil {
			return
		}
		if !from.IsIP() {
			log.Warnln("server returned an invalid UDP source (%s), force replace to (%s)", from, oAddrPort)
			from = M.SocksaddrFromNetIP(oAddrPort)
		}
		// restore DestinationNAT
		from.Addr = sender.RestoreReadFrom(from.Addr.Unmap()).Unmap()
		from.Fqdn = ""
		err = C.WriteBackBuffer(writeBack, buffer, from)
		if err != nil {
			return
		}
	}
}

func closeAllLocalCoon(lAddr string) {
	natTable.RangeForLocalConn(lAddr, func(key string, value *net.UDPConn) bool {
		conn := value

		conn.Close()
		log.Debugln("Closing TProxy local conn... lAddr=%s rAddr=%s", lAddr, key)
		return true
	})
}

func handleSocket(inbound, outbound net.Conn) {
	N.Relay(inbound, outbound)
}

package snell

import (
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"net"
	"net/netip"
	"sync"
	"sync/atomic"

	"github.com/metacubex/sing/common/buf"
	M "github.com/metacubex/sing/common/metadata"

	"github.com/metacubex/mihomo/common/pool"
	"github.com/metacubex/mihomo/transport/shadowsocks/shadowaead"
	"github.com/metacubex/mihomo/transport/socks5"
)

const (
	Version1            = 1
	Version2            = 2
	Version3            = 3
	Version4            = 4
	Version5            = 5
	Version6            = 6
	DefaultSnellVersion = Version1

	// max packet length
	maxLength = 0x3FFF
)

const (
	CommandPing       byte = 0
	CommandConnect    byte = 1
	CommandConnectV2  byte = 5
	CommandUDP        byte = 6
	CommondUDPForward byte = 1

	CommandTunnel byte = 0
	CommandPong   byte = 1
	CommandError  byte = 2

	Version byte = 1
)

var endSignal = []byte{}

type packetFrameWriter interface {
	WritePacketFrame([]byte) (int, error)
}

type Snell struct {
responseBuffers [1]*buf.Buffer
	net.Conn
	buffer [1]byte
	reply  bool
}

func (s *Snell) Read(b []byte) (int, error) {
	if err := s.ReadReply(); err != nil {
		return 0, err
	}
	return s.Conn.Read(b)
}

// ReadPacketBuffer preserves record boundaries and ownership for UDP ingress.
func (s *Snell) ReadPacketBuffer() (*buf.Buffer, error) {
	if err := s.ReadReply(); err != nil {
		return nil, err
	}
	if reader, ok := s.Conn.(interface{ ReadPacketBuffer() (*buf.Buffer, error) }); ok {
		return reader.ReadPacketBuffer()
	}
	buffer := buf.NewSize(maxLength)
	n, err := s.Conn.Read(buffer.FreeBytes())
	if err != nil {
		buffer.Release()
		return nil, err
	}
	buffer.Resize(0, n)
	return buffer, nil
}

func (s *Snell) ReadReply() error {
	if s.reply {
		return nil
	}

	if _, err := io.ReadFull(s.Conn, s.buffer[:]); err != nil {
		return err
	}
	s.reply = true

	if s.buffer[0] == CommandTunnel {
		return nil
	} else if s.buffer[0] != CommandError {
		return errors.New("command not support")
	}

	// CommandError
	// 1 byte error code
	if _, err := io.ReadFull(s.Conn, s.buffer[:]); err != nil {
		return err
	}
	errcode := int(s.buffer[0])

	// 1 byte error message length
	if _, err := io.ReadFull(s.Conn, s.buffer[:]); err != nil {
		return err
	}
	length := int(s.buffer[0])
	msg := make([]byte, length)

	if _, err := io.ReadFull(s.Conn, msg); err != nil {
		return err
	}

	return fmt.Errorf("server reported code: %d, message: %s", errcode, string(msg))
}

func WriteHeader(conn net.Conn, host string, port uint, version int) error {
	return WriteHeaderWithReuse(conn, host, port, version, false)
}

func WriteHeaderWithReuse(conn net.Conn, host string, port uint, version int, reuse bool) error {
	buf := pool.GetBuffer()
	defer pool.PutBuffer(buf)
	buf.WriteByte(Version)
	if version == Version2 || reuse {
		buf.WriteByte(CommandConnectV2)
	} else {
		buf.WriteByte(CommandConnect)
	}

	// clientID length & id
	buf.WriteByte(0)

	// host & port
	buf.WriteByte(uint8(len(host)))
	buf.WriteString(host)
	binary.Write(buf, binary.BigEndian, uint16(port))

	if _, err := conn.Write(buf.Bytes()); err != nil {
		return err
	}

	return nil
}

func WriteUDPHeader(conn net.Conn, version int) error {
	if version < Version3 {
		return errors.New("unsupport UDP version")
	}

	// version, command, clientID length
	_, err := conn.Write([]byte{Version, CommandUDP, 0x00})
	return err
}

func writeZeroChunk(conn net.Conn) error {
	if _, err := conn.Write(endSignal); err != nil {
		return err
	}
	return nil
}

// HalfClose only works after the request negotiated the reuse command.
func HalfClose(conn net.Conn) error {
	if err := writeZeroChunk(conn); err != nil {
		return err
	}
	if s, ok := conn.(*Snell); ok {
		s.reply = false
	}
	return nil
}

func StreamConn(conn net.Conn, psk []byte, version int) *Snell {
	if version >= Version4 {
		return &Snell{Conn: newV4Conn(conn, psk)}
	}

	var cipher shadowaead.Cipher
	if version != Version1 {
		cipher = NewAES128GCM(psk)
	} else {
		cipher = NewChacha20Poly1305(psk)
	}
	return &Snell{Conn: shadowaead.NewConn(conn, cipher)}
}

func ServerStreamConn(conn net.Conn, psk []byte, version int) *Snell {
	stream := StreamConn(conn, psk, version)
	stream.reply = true
	return stream
}

func PacketConn(conn net.Conn) net.PacketConn {
	return &packetConn{
		Conn: conn,
	}
}

func (s *Snell) WritePacketFrame(b []byte) (int, error) {
	if fw, ok := s.Conn.(packetFrameWriter); ok {
		return fw.WritePacketFrame(b)
	}
	return s.Conn.Write(b)
}

func writePacket(w io.Writer, socks5Addr, payload []byte) (int, error) {
	buf := pool.GetBuffer()
	defer pool.PutBuffer(buf)

	// compose snell UDP address format (refer: icpz/snell-server-reversed)
	// a brand new wheel to replace socks5 address format, well done Yachen
	buf.WriteByte(CommondUDPForward)
	switch socks5Addr[0] {
	case socks5.AtypDomainName:
		hostLen := socks5Addr[1]
		if len(socks5Addr) < 1+1+int(hostLen)+2 {
			return 0, errors.New("snell UDP address invalid")
		}
		buf.Write(socks5Addr[1 : 1+1+hostLen+2])
	case socks5.AtypIPv4:
		if len(socks5Addr) < 1+net.IPv4len+2 {
			return 0, errors.New("snell UDP address invalid")
		}
		buf.Write([]byte{0x00, 0x04})
		buf.Write(socks5Addr[1 : 1+net.IPv4len+2])
	case socks5.AtypIPv6:
		if len(socks5Addr) < 1+net.IPv6len+2 {
			return 0, errors.New("snell UDP address invalid")
		}
		buf.Write([]byte{0x00, 0x06})
		buf.Write(socks5Addr[1 : 1+net.IPv6len+2])
	default:
		return 0, errors.New("snell UDP address invalid")
	}

	buf.Write(payload)
	if fw, ok := w.(packetFrameWriter); ok {
		_, err := fw.WritePacketFrame(buf.Bytes())
		if err != nil {
			return 0, err
		}
		return len(payload), nil
	}

	_, err := w.Write(buf.Bytes())
	if err != nil {
		return 0, err
	}
	return len(payload), nil
}

func WritePacket(w io.Writer, socks5Addr, payload []byte) (int, error) {
	maxPayloadLength := maxLength - UdpRequestHeaderLength(socks5Addr)
	if maxPayloadLength <= 0 {
		return 0, errors.New("snell UDP address too large")
	}
	if len(payload) <= maxPayloadLength {
		return writePacket(w, socks5Addr, payload)
	}
	return 0, errors.New("snell UDP payload too large")
}

func WritePacketResponse(w io.Writer, addr net.Addr, payload []byte) (int, error) {
	buf := pool.GetBuffer()
	defer pool.PutBuffer(buf)

	socks5Addr := socks5.ParseAddrToSocksAddr(addr)
	if len(socks5Addr) == 0 {
		return 0, errors.New("snell UDP response address invalid")
	}
	switch socks5Addr[0] {
	case socks5.AtypIPv4:
		if len(socks5Addr) < 1+net.IPv4len+2 {
			return 0, errors.New("snell UDP response address invalid")
		}
		buf.WriteByte(0x04)
		buf.Write(socks5Addr[1 : 1+net.IPv4len+2])
	case socks5.AtypIPv6:
		if len(socks5Addr) < 1+net.IPv6len+2 {
			return 0, errors.New("snell UDP response address invalid")
		}
		buf.WriteByte(0x06)
		buf.Write(socks5Addr[1 : 1+net.IPv6len+2])
	default:
		return 0, errors.New("snell UDP response address invalid")
	}
	buf.Write(payload)

	var err error
	var written int
	if fw, ok := w.(packetFrameWriter); ok {
		written, err = fw.WritePacketFrame(buf.Bytes())
	} else {
		written, err = w.Write(buf.Bytes())
	}
	if written == buf.Len() {
		return len(payload), err
	}
	if err == nil {
		err = io.ErrShortWrite
	}
	return 0, err
}

type UDPRequest struct {
	Host    string
	Ip      netip.Addr
	Port    uint16
	Payload []byte
}

func ParseUDPRequest(packet []byte) (UDPRequest, error) {
	if len(packet) < 2 || packet[0] != CommondUDPForward {
		return UDPRequest{}, errors.New("snell invalid UDP request")
	}
	if hostLen := int(packet[1]); hostLen != 0 {
		if len(packet) < 2+hostLen+2 {
			return UDPRequest{}, errors.New("snell invalid UDP domain request")
		}
		offset := 2 + hostLen
		return UDPRequest{
			Host:    string(packet[2:offset]),
			Port:    binary.BigEndian.Uint16(packet[offset : offset+2]),
			Payload: packet[offset+2:],
		}, nil
	}
	if len(packet) < 3 {
		return UDPRequest{}, errors.New("snell invalid UDP IP request")
	}
	switch packet[2] {
	case 0x04:
		if len(packet) < 3+net.IPv4len+2 {
			return UDPRequest{}, errors.New("snell invalid UDP IPv4 request")
		}
		offset := 3 + net.IPv4len
		ip, _ := netip.AddrFromSlice(packet[3:offset])
		return UDPRequest{
			Ip:      ip.Unmap(),
			Port:    binary.BigEndian.Uint16(packet[offset : offset+2]),
			Payload: packet[offset+2:],
		}, nil
	case 0x06:
		if len(packet) < 3+net.IPv6len+2 {
			return UDPRequest{}, errors.New("snell invalid UDP IPv6 request")
		}
		offset := 3 + net.IPv6len
		ip, _ := netip.AddrFromSlice(packet[3:offset])
		return UDPRequest{
			Ip:      ip.Unmap(),
			Port:    binary.BigEndian.Uint16(packet[offset : offset+2]),
			Payload: packet[offset+2:],
		}, nil
	default:
		return UDPRequest{}, errors.New("snell invalid UDP address type")
	}
}

func UdpRequestHeaderLength(socks5Addr []byte) int {
	if len(socks5Addr) == 0 {
		return maxLength + 1
	}
	switch socks5Addr[0] {
	case socks5.AtypDomainName:
		if len(socks5Addr) < 2 {
			return maxLength + 1
		}
		return 1 + 1 + int(socks5Addr[1]) + 2
	case socks5.AtypIPv4:
		return 1 + 2 + net.IPv4len + 2
	case socks5.AtypIPv6:
		return 1 + 2 + net.IPv6len + 2
	default:
		return maxLength + 1
	}
}

func ReadPacket(r io.Reader, payload []byte) (net.Addr, int, error) {
	// Read a complete protocol record even when the general UDP pool is smaller.
	buf := pool.Get(maxLength)
	defer pool.Put(buf)

	n, err := r.Read(buf)
	headLen := 1
	if err != nil {
		return nil, 0, err
	}
	if n < headLen {
		return nil, 0, errors.New("insufficient UDP length")
	}

	// parse snell UDP response address format
	switch buf[0] {
	case 0x04:
		headLen += net.IPv4len + 2
		if n < headLen {
			err = errors.New("insufficient UDP length")
			break
		}
		buf[0] = socks5.AtypIPv4
	case 0x06:
		headLen += net.IPv6len + 2
		if n < headLen {
			err = errors.New("insufficient UDP length")
			break
		}
		buf[0] = socks5.AtypIPv6
	default:
		err = errors.New("ip version invalid")
	}

	if err != nil {
		return nil, 0, err
	}

	addr := socks5.SplitAddr(buf[0:])
	if addr == nil {
		return nil, 0, errors.New("remote address invalid")
	}
	uAddr := addr.UDPAddr()
	if uAddr == nil {
		return nil, 0, errors.New("parse addr error")
	}

	length := len(payload)
	if n-headLen < length {
		length = n - headLen
	}
	copy(payload[:], buf[headLen:headLen+length])

	return uAddr, length, nil
}

type packetConn struct {
	net.Conn
	rMux      sync.Mutex
	wMux      sync.Mutex
	writeErr  error
	closed    atomic.Bool
	closeOnce sync.Once
	closeErr  error
}

func (pc *packetConn) WritePacketFrame(b []byte) (int, error) {
	if s, ok := pc.Conn.(*Snell); ok {
		if fw, ok := s.Conn.(packetFrameWriter); ok {
			return fw.WritePacketFrame(b)
		}
	}
	return pc.Conn.Write(b)
}

func (pc *packetConn) WriteTo(b []byte, addr net.Addr) (int, error) {
	if _, ok := pc.frameBatchWriter(); ok {
		n, err := pc.WritePacketBatchCount([]*buf.Buffer{buf.As(b)}, []M.Socksaddr{M.SocksaddrFromNet(addr)})
		if n == 1 {
			return len(b), err
		}
		return 0, err
	}
	pc.wMux.Lock()
	defer pc.wMux.Unlock()

	return WritePacket(pc, socks5.ParseAddrToSocksAddr(addr), b)
}

func (pc *packetConn) ReadFrom(b []byte) (int, net.Addr, error) {
	pc.rMux.Lock()
	defer pc.rMux.Unlock()

	addr, n, err := ReadPacket(pc.Conn, b)
	if err != nil {
		return 0, nil, err
	}

	return n, addr, nil
}

